//! Acquires canonical owners after the complete original index/type checks.
use super::*;
fn shared<T: nominal_payload::NominalElement, E>(
    values: &mut NominalPayload<T>,
    reserve: &mut impl FnMut(usize) -> Result<(), E>,
) -> Result<(), E> {
    if values.is_shared() {
        return reserve(0);
    }
    if values.is_empty() {
        // Empty metadata owns no payload backing to share. Moving its legacy
        // Vec carrier avoids a control block per monomorphic function.
        return reserve(std::mem::size_of::<NominalPayload<T>>());
    }
    let owner = NominalPayload::from_funded_vec(&mut **values, reserve)?;
    *values = owner;
    Ok(())
}
impl DeclarationIndex {
    pub(super) fn drain_legacy_type_roots(&mut self, mut dispose: impl FnMut(ResolvedType)) {
        for (_, fields) in std::mem::take(&mut self.case_fields) {
            fields.drain(&mut dispose);
        }
        for (_, fields) in std::mem::take(&mut self.record_fields) {
            if !fields.is_shared() {
                fields.drain_recursive_types(&mut dispose);
            }
        }
        for (_, cases) in std::mem::take(&mut self.variant_cases) {
            if !cases.is_shared() {
                cases.drain_recursive_types(&mut dispose);
            }
        }
    }

    pub(in crate::hir) fn record_payload(
        &self,
        owner: &DeclarationId,
    ) -> Option<&NominalPayload<ResolvedFieldDeclaration>> {
        self.record_fields.get(owner)
    }
    pub(in crate::hir) fn case_payload(
        &self,
        owner: &DeclarationId,
    ) -> Option<&NominalPayload<ResolvedVariantCaseDeclaration>> {
        self.variant_cases.get(owner)
    }
    pub(in crate::hir) fn parameter_payload(
        &self,
        owner: &DeclarationId,
    ) -> Option<&NominalPayload<ResolvedTypeParameterDeclaration>> {
        self.type_parameters.get(owner)
    }

    pub(super) fn share_nominal_payloads<E>(
        &mut self,
        reserve: &mut impl FnMut(usize) -> Result<(), E>,
    ) -> Result<(), E> {
        for values in self.type_parameters.values_mut() {
            shared(values, reserve)?;
        }
        for values in self.record_fields.values_mut() {
            shared(values, reserve)?;
        }
        for values in self.variant_cases.values_mut() {
            shared(values, reserve)?;
        }
        for cases in self.variant_cases.values() {
            for (ordinal, case) in cases.iter().enumerate() {
                reserve(std::mem::size_of::<CaseFields>())?;
                self.case_fields.insert(
                    case.id.clone(),
                    CaseFields::canonical(cases.clone(), ordinal),
                );
            }
        }
        Ok(())
    }
}

//! Trusted current compiler prelude coordinates, not ID-based source authority.
use super::*;
use crate::hir::prelude_bundle::BasePreludeBundle;
use std::mem::size_of;
impl DeclarationIndex {
    pub(super) fn base_type_for_source<'a>(
        base: Option<&'a BasePreludeBundle>,
        prelude: &[crate::ast::TypeDeclaration],
        declaration: &crate::ast::TypeDeclaration,
    ) -> Option<&'a ResolvedTypeDeclaration> {
        let base = base?;
        let current = crate::prelude::declarations();
        // Only the exact compiler-owned source pair may use schema payloads.
        // Authored or decoded declarations with matching IDs substitute nothing.
        if prelude.len() < 2 || !std::ptr::eq(&prelude[..2], &current[..2]) {
            return None;
        }
        let ordinal = prelude[..2]
            .iter()
            .position(|item| std::ptr::eq(item, declaration))?;
        base.types_slice().get(ordinal)
    }
    pub(super) fn compiler_type_for_source<'a>(
        base: Option<&'a BasePreludeBundle>,
        vector: Option<&'a crate::hir::prelude_bundle::VectorExtension>,
        prelude: &[crate::ast::TypeDeclaration],
        declaration: &crate::ast::TypeDeclaration,
    ) -> Option<&'a ResolvedTypeDeclaration> {
        Self::base_type_for_source(base, prelude, declaration).or_else(|| {
            crate::hir::prelude_bundle::VectorExtension::for_source(vector, prelude, declaration)
        })
    }
    pub(super) fn reserve_base_receivers<E>(
        base: &BasePreludeBundle,
        reserve: &mut impl FnMut(usize) -> Result<(), E>,
    ) -> Result<(), E> {
        fn node<K, V>() -> usize {
            crate::cleanup_plan::replay_btree_node_upper::<K, V>()
                .expect("fixed base receiving map layout")
        }
        // Full new metadata map backing and simultaneous initializer/receivers;
        // unchanged enclosing forecast receives no subtraction or payload credit.
        for declaration in base.declarations_slice() {
            let names = 2 * declaration.name.len() + 2 * size_of::<String>();
            let map = if declaration.owner.is_none() {
                node::<String, DeclarationId>()
            } else {
                node::<(DeclarationId, String), DeclarationId>()
            };
            reserve(
                names + map + node::<DeclarationId, Declaration>() + 2 * size_of::<Declaration>(),
            )?;
        }
        for _ in base.types_slice() {
            reserve(
                2 * size_of::<ResolvedTypeDeclaration>()
                    + size_of::<Result<ResolvedTypeDeclaration, Diagnostic>>()
                    + 2 * size_of::<NominalPayload<ResolvedTypeParameterDeclaration>>()
                    + 2 * size_of::<NominalPayload<ResolvedVariantCaseDeclaration>>(),
            )?;
        }
        Ok(())
    }
    pub(super) fn insert_base_variant(&mut self, ty: &ResolvedTypeDeclaration) {
        let ResolvedTypeDeclarationKind::Variant { cases } = &ty.kind else {
            unreachable!("sealed base variant")
        };
        for case in cases {
            self.insert_case(
                ty.id.clone(),
                case.name.clone(),
                case.id.clone(),
                IdentityOrigin::CompilerOwned,
            );
            for field in &case.fields {
                self.fields_by_owner_name
                    .insert((case.id.clone(), field.name.clone()), field.id.clone());
                self.declarations.insert(
                    field.id.clone(),
                    Declaration {
                        id: field.id.clone(),
                        name: field.name.clone(),
                        kind: DeclarationKind::CaseField,
                        identity_origin: IdentityOrigin::CompilerOwned,
                        owner: Some(case.id.clone()),
                    },
                );
            }
        }
        self.variant_cases.insert(ty.id.clone(), cases.clone());
    }
}

//! Complete pre-OPT827 producer; only receiver name differs.
use super::*;
use identity_payer::IdentityIndexError;
impl DeclarationIndex {
    pub(in crate::hir) fn nominal_original_with_prelude(
        program: &dyn ProgramSource,
        prelude: &[crate::ast::TypeDeclaration],
    ) -> Result<Self, Diagnostic> {
        Self::nominal_original_with_identity_payer(program, prelude, &mut |text| {
            Ok::<_, std::convert::Infallible>(DeclarationId::new(text))
        })
        .map_err(|error| match error {
            IdentityIndexError::Semantic(error) => error,
            IdentityIndexError::Identity(impossible) => match impossible {},
        })
    }

    pub(in crate::hir) fn nominal_original_with_identity_payer<E>(
        program: &dyn ProgramSource,
        prelude: &[crate::ast::TypeDeclaration],
        identity: &mut dyn FnMut(&str) -> Result<DeclarationId, E>,
    ) -> Result<Self, IdentityIndexError<E>> {
        let mut index = Self::default();
        for declaration in program.types().iter().chain(prelude) {
            let kind = match declaration.kind {
                TypeDeclarationKind::Resource { .. } => DeclarationKind::Resource,
                TypeDeclarationKind::Record { .. } => DeclarationKind::Record,
                TypeDeclarationKind::Class { .. } => DeclarationKind::Class,
                TypeDeclarationKind::Variant { .. } => DeclarationKind::Variant,
            };
            index.insert_top_level(
                declaration.name.clone(),
                identity(&declaration.stable_id).map_err(IdentityIndexError::Identity)?,
                kind,
                if crate::prelude::is_compiler_owned_id(&declaration.stable_id) {
                    IdentityOrigin::CompilerOwned
                } else if declaration.explicit_id {
                    IdentityOrigin::Explicit
                } else {
                    IdentityOrigin::Automatic
                },
            );
            let owner = index.inserted_identity(&declaration.stable_id);
            let parameters = declaration
                .type_parameters
                .iter()
                .enumerate()
                .map(|(ordinal, parameter)| {
                    Ok(ResolvedTypeParameterDeclaration {
                        name: parameter.name.clone(),
                        index: u32::try_from(ordinal).map_err(|_| {
                            Diagnostic::error(
                                "SPX-H006",
                                format!("type `{}` has too many parameters", declaration.name),
                                declaration.span,
                            )
                            .at_path(program.path())
                        })?,
                        span: parameter.span,
                    })
                })
                .collect::<Result<Vec<_>, Diagnostic>>()?;
            index.type_parameters.insert(owner, parameters);
        }
        for interface in program.interfaces() {
            let interface_id =
                identity(&interface.stable_id).map_err(IdentityIndexError::Identity)?;
            index.insert_top_level(
                interface.name.clone(),
                interface_id.clone(),
                DeclarationKind::Interface,
                IdentityOrigin::Explicit,
            );
            for import in &interface.imports {
                let import_id =
                    identity(&import.stable_id).map_err(IdentityIndexError::Identity)?;
                index
                    .imports_by_key
                    .insert(import.stable_id.clone(), import_id.clone());
                if import.native_rust {
                    index
                        .native_rust_imports_by_name
                        .insert(import.name.clone(), import_id.clone());
                }
                index.insert_owned_declaration(
                    interface_id.clone(),
                    import.name.clone(),
                    import_id,
                    DeclarationKind::Import,
                    IdentityOrigin::Explicit,
                );
            }
        }
        for declaration in program.types().iter().chain(prelude) {
            let TypeDeclarationKind::Resource { lifecycles } = &declaration.kind else {
                continue;
            };
            if let [lifecycle] = lifecycles.as_slice() {
                let lifecycle_id = lifecycle
                    .stable_id
                    .as_ref()
                    .expect("verified lifecycle has an explicit identity");
                index.insert_owned_declaration(
                    index.inserted_identity(&declaration.stable_id),
                    "drop".to_owned(),
                    identity(lifecycle_id).map_err(IdentityIndexError::Identity)?,
                    DeclarationKind::ResourceDrop,
                    IdentityOrigin::Explicit,
                );
            }
        }
        for function in program.functions() {
            let owner = identity(&function.stable_id).map_err(IdentityIndexError::Identity)?;
            index.insert_top_level(
                function.name.clone(),
                owner.clone(),
                DeclarationKind::Function,
                if super::record_invariants::is_synthesized(&function.name) {
                    IdentityOrigin::CompilerOwned
                } else if function.explicit_id {
                    IdentityOrigin::Explicit
                } else {
                    IdentityOrigin::Automatic
                },
            );
            let parameters = function
                .type_parameters
                .iter()
                .enumerate()
                .map(|(ordinal, parameter)| {
                    Ok(ResolvedTypeParameterDeclaration {
                        name: parameter.name.clone(),
                        index: u32::try_from(ordinal).map_err(|_| {
                            Diagnostic::error(
                                "SPX-H006",
                                format!("function `{}` has too many parameters", function.name),
                                function.span,
                            )
                            .at_path(program.path())
                        })?,
                        span: parameter.span,
                    })
                })
                .collect::<Result<Vec<_>, Diagnostic>>()?;
            index.type_parameters.insert(owner, parameters);
        }
        if program
            .interfaces()
            .iter()
            .flat_map(|interface| &interface.imports)
            .filter(|import| import.native_rust)
            .any(|import| index.functions_by_name.contains_key(&import.name))
        {
            return Err(IdentityIndexError::Semantic(
                Diagnostic::error(
                    "SPX-B107",
                    "Native Rust Interop declaration set is unsupported: symbol collision",
                    Span::default(),
                )
                .at_path(program.path()),
            ));
        }
        for declaration in program.types().iter().chain(prelude) {
            let (TypeDeclarationKind::Record { fields }
            | TypeDeclarationKind::Class { fields, .. }) = &declaration.kind
            else {
                continue;
            };
            let owner = index.inserted_identity(&declaration.stable_id);
            let mut resolved_fields = Vec::with_capacity(fields.len());
            for (ordinal, field) in fields.iter().enumerate() {
                let ty = index
                    .resolve_source_type(&field.ty, Some(&owner))
                    .ok_or_else(|| {
                        Diagnostic::error(
                            "SPX-H001",
                            format!("unresolved field type `{}`", field.ty),
                            field.span,
                        )
                        .at_path(program.path())
                    })?;
                let field_index = u32::try_from(ordinal).map_err(|_| {
                    Diagnostic::error(
                        "SPX-H006",
                        format!("record `{}` has too many fields", declaration.name),
                        declaration.span,
                    )
                    .at_path(program.path())
                })?;
                let resolved = ResolvedFieldDeclaration {
                    id: identity(&field.stable_id).map_err(IdentityIndexError::Identity)?,
                    name: field.name.clone(),
                    index: field_index,
                    ty,
                    span: field.span,
                };
                index.insert_field(
                    owner.clone(),
                    resolved.clone(),
                    if field.explicit_id {
                        IdentityOrigin::Explicit
                    } else {
                        IdentityOrigin::Automatic
                    },
                );
                resolved_fields.push(resolved);
            }
            index.record_fields.insert(owner, resolved_fields);
        }
        for declaration in program.types().iter() {
            let TypeDeclarationKind::Class { fields, methods } = &declaration.kind else {
                continue;
            };
            let owner = index.inserted_identity(&declaration.stable_id);
            let mut resolved_fields = Vec::with_capacity(fields.len());
            for (ordinal, field) in fields.iter().enumerate() {
                let ty = index
                    .resolve_source_type(&field.ty, Some(&owner))
                    .ok_or_else(|| {
                        Diagnostic::error(
                            "SPX-H001",
                            format!("unresolved class field type `{}`", field.ty),
                            field.span,
                        )
                        .at_path(program.path())
                    })?;
                let field_index = u32::try_from(ordinal).map_err(|_| {
                    Diagnostic::error(
                        "SPX-H006",
                        format!("class `{}` has too many fields", declaration.name),
                        declaration.span,
                    )
                    .at_path(program.path())
                })?;
                let resolved = ResolvedFieldDeclaration {
                    id: identity(&field.stable_id).map_err(IdentityIndexError::Identity)?,
                    name: field.name.clone(),
                    index: field_index,
                    ty,
                    span: field.span,
                };
                index.insert_field(
                    owner.clone(),
                    resolved.clone(),
                    if field.explicit_id {
                        IdentityOrigin::Explicit
                    } else {
                        IdentityOrigin::Automatic
                    },
                );
                resolved_fields.push(resolved);
            }
            index.record_fields.insert(owner.clone(), resolved_fields);
            for method in methods {
                let method_id =
                    identity(&method.stable_id).map_err(IdentityIndexError::Identity)?;
                if index.declarations.contains_key(&method_id) {
                    return Err(IdentityIndexError::Semantic(
                        Diagnostic::error(
                            "SPX-S102",
                            format!("duplicate stable id `{}`", method.stable_id),
                            method.span,
                        )
                        .at_path(program.path()),
                    ));
                }
                index.insert_owned_declaration(
                    owner.clone(),
                    method.name.clone(),
                    method_id,
                    DeclarationKind::Function,
                    if method.explicit_id {
                        IdentityOrigin::Explicit
                    } else {
                        IdentityOrigin::Automatic
                    },
                );
                if !method.type_parameters.is_empty() {
                    return Err(IdentityIndexError::Semantic(
                        Diagnostic::error(
                            "SPX-T224",
                            format!(
                                "class method `{}` cannot declare generic parameters in this slice",
                                method.name
                            ),
                            method.span,
                        )
                        .at_path(program.path()),
                    ));
                }
                index
                    .type_parameters
                    .insert(index.inserted_identity(&method.stable_id), Vec::new());
            }
        }
        for declaration in program.types().iter().chain(prelude) {
            let TypeDeclarationKind::Variant { cases } = &declaration.kind else {
                continue;
            };
            let owner = index.inserted_identity(&declaration.stable_id);
            let mut resolved_cases = Vec::with_capacity(cases.len());
            for (case_ordinal, case) in cases.iter().enumerate() {
                let case_id = identity(&case.stable_id).map_err(IdentityIndexError::Identity)?;
                let case_index = u32::try_from(case_ordinal).map_err(|_| {
                    Diagnostic::error(
                        "SPX-H006",
                        format!("variant `{}` has too many cases", declaration.name),
                        declaration.span,
                    )
                    .at_path(program.path())
                })?;
                index.insert_case(
                    owner.clone(),
                    case.name.clone(),
                    case_id.clone(),
                    if crate::prelude::is_compiler_owned_id(&case.stable_id) {
                        IdentityOrigin::CompilerOwned
                    } else if case.explicit_id {
                        IdentityOrigin::Explicit
                    } else {
                        IdentityOrigin::Automatic
                    },
                );
                let mut resolved_fields = Vec::with_capacity(case.fields.len());
                for (field_ordinal, field) in case.fields.iter().enumerate() {
                    let ty = index
                        .resolve_source_type(&field.ty, Some(&owner))
                        .ok_or_else(|| {
                            Diagnostic::error(
                                "SPX-H001",
                                format!("unresolved case field type `{}`", field.ty),
                                field.span,
                            )
                            .at_path(program.path())
                        })?;
                    let field_index = u32::try_from(field_ordinal).map_err(|_| {
                        Diagnostic::error(
                            "SPX-H006",
                            format!(
                                "variant case `{}::{}` has too many fields",
                                declaration.name, case.name
                            ),
                            case.span,
                        )
                        .at_path(program.path())
                    })?;
                    let resolved = ResolvedFieldDeclaration {
                        id: identity(&field.stable_id).map_err(IdentityIndexError::Identity)?,
                        name: field.name.clone(),
                        index: field_index,
                        ty,
                        span: field.span,
                    };
                    index.insert_case_field(
                        case_id.clone(),
                        resolved.clone(),
                        if crate::prelude::is_compiler_owned_id(&field.stable_id) {
                            IdentityOrigin::CompilerOwned
                        } else if field.explicit_id {
                            IdentityOrigin::Explicit
                        } else {
                            IdentityOrigin::Automatic
                        },
                    );
                    resolved_fields.push(resolved);
                }
                index
                    .case_fields
                    .insert(case_id.clone(), resolved_fields.clone());
                resolved_cases.push(ResolvedVariantCaseDeclaration {
                    id: case_id,
                    name: case.name.clone(),
                    index: case_index,
                    fields: resolved_fields,
                    span: case.span,
                });
            }
            index.variant_cases.insert(owner, resolved_cases);
        }
        index.materialize_class_inheritance(program)?;
        if !index.populate_type_facts() {
            return Err(IdentityIndexError::Semantic(
                Diagnostic::error(
                    "SPX-T217",
                    "record declarations contain an illegal by-value recursive layout",
                    Span::default(),
                )
                .at_path(program.path()),
            ));
        }
        Ok(index)
    }
}

//! Source-shaped disposal frontier acquired on the same actual caller owner.
//! This scratch is storage only; neither source admission nor a type proof.
use super::*;
use std::{
    mem::size_of,
    ops::{Deref, DerefMut},
    sync::{Arc, Mutex},
};
type Scratch = Arc<Mutex<Vec<ResolvedType>>>;
#[derive(Default)]
pub(in crate::hir) struct Workspace {
    pub(super) scratch: Option<Scratch>,
    pub(super) building: bool,
}
// Published canonical indexes own no legacy recursive field Vec. Their clones
// share payload owners, each of which already owns its own disposal scratch.
impl Clone for Workspace {
    fn clone(&self) -> Self {
        Self::default()
    }
}
impl PartialEq for Workspace {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}
impl Eq for Workspace {}
impl std::fmt::Debug for Workspace {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("private disposal storage")
    }
}
fn frontier<E>(root: &Type, reserve: &mut impl FnMut(usize) -> Result<(), E>) -> Result<usize, E> {
    fn push<'a, E>(
        stack: &mut Vec<&'a Type>,
        ty: &'a Type,
        reserve: &mut impl FnMut(usize) -> Result<(), E>,
    ) -> Result<(), E> {
        if stack.len() == stack.capacity() {
            let cap = stack.capacity().saturating_mul(2).max(4);
            reserve(
                size_of::<Vec<&Type>>().saturating_add(cap.saturating_mul(size_of::<&Type>())),
            )?;
            let mut next = Vec::with_capacity(cap);
            assert_eq!(next.capacity(), cap);
            next.append(stack);
            *stack = next;
        }
        stack.push(ty);
        Ok(())
    }
    if !matches!(root,Type::Named{arguments,..} if !arguments.is_empty())
        && !matches!(root, Type::Function { .. })
    {
        return Ok(0);
    }
    let mut stack = Vec::new();
    push(&mut stack, root, reserve)?;
    let mut maximum = 0;
    while let Some(ty) = stack.pop() {
        match ty {
            Type::Named { arguments, .. } => {
                for child in arguments {
                    push(&mut stack, child, reserve)?;
                }
            }
            Type::Function { parameters, result } => {
                for child in parameters {
                    push(&mut stack, child, reserve)?;
                }
                push(&mut stack, result, reserve)?;
            }
            _ => {}
        }
        maximum = maximum.max(stack.len());
    }
    Ok(maximum)
}
/// Construction-only Vec guard. The original Vec allocation and order are
/// unchanged; all local recursive values share the one prepaid rollback frontier.
pub(super) struct PendingVec<T: nominal_payload::NominalElement> {
    values: Vec<T>,
    scratch: Option<Scratch>,
}
impl<T: nominal_payload::NominalElement> PendingVec<T> {
    pub(super) fn into_vec(mut self) -> Vec<T> {
        std::mem::take(&mut self.values)
    }
}
impl<T: nominal_payload::NominalElement> Deref for PendingVec<T> {
    type Target = Vec<T>;
    fn deref(&self) -> &Vec<T> {
        &self.values
    }
}
impl<T: nominal_payload::NominalElement> DerefMut for PendingVec<T> {
    fn deref_mut(&mut self) -> &mut Vec<T> {
        &mut self.values
    }
}
impl<T: nominal_payload::NominalElement> Drop for PendingVec<T> {
    fn drop(&mut self) {
        if let Some(scratch) = &self.scratch {
            let mut scratch = scratch.lock().expect("construction disposal lock");
            for value in &mut self.values {
                value.drain_types(&mut |ty| nominal_payload::dispose(ty, &mut scratch));
            }
        }
    }
}
pub(super) struct PendingType {
    value: Option<ResolvedType>,
    scratch: Option<Scratch>,
}
impl PendingType {
    pub(super) fn into_type(mut self) -> ResolvedType {
        self.value.take().expect("present construction type")
    }
}
impl Drop for PendingType {
    fn drop(&mut self) {
        if let (Some(ty), Some(scratch)) = (self.value.take(), &self.scratch) {
            nominal_payload::dispose(ty, &mut scratch.lock().expect("construction disposal lock"));
        }
    }
}
pub(super) struct PendingTypes {
    values: Vec<ResolvedType>,
    scratch: Option<Scratch>,
}
impl PendingTypes {
    pub(super) fn into_vec(mut self) -> Vec<ResolvedType> {
        std::mem::take(&mut self.values)
    }
}
impl Deref for PendingTypes {
    type Target = Vec<ResolvedType>;
    fn deref(&self) -> &Self::Target {
        &self.values
    }
}
impl DerefMut for PendingTypes {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.values
    }
}
impl Drop for PendingTypes {
    fn drop(&mut self) {
        if let Some(s) = &self.scratch {
            let mut s = s.lock().expect("construction disposal lock");
            for ty in self.values.drain(..) {
                nominal_payload::dispose(ty, &mut s);
            }
        }
    }
}
impl Workspace {
    pub(super) fn types(&self) -> PendingTypes {
        PendingTypes {
            values: Vec::new(),
            scratch: self.scratch.clone(),
        }
    }
    pub(super) fn fields<T: nominal_payload::NominalElement>(
        &self,
        capacity: usize,
    ) -> PendingVec<T> {
        PendingVec {
            values: Vec::with_capacity(capacity),
            scratch: self.scratch.clone(),
        }
    }
    pub(super) fn resolved_type(&self, value: ResolvedType) -> PendingType {
        PendingType {
            value: Some(value),
            scratch: self.scratch.clone(),
        }
    }
    pub(super) fn finish(&mut self) {
        self.building = false;
        // Every published nonempty sequence now has its own immutable paid
        // owner. Never apply a source frontier to later host-mutated values.
        self.scratch = None;
    }
    pub(super) fn acquire<E>(
        program: &dyn ProgramSource,
        prelude: &[crate::ast::TypeDeclaration],
        reserve: &mut impl FnMut(usize) -> Result<(), E>,
    ) -> Result<Self, E> {
        // Replacing Vec map values enlarges actual BTree nodes. Acquire a
        // complete current node upper bound per possible insertion in each
        // changed map, in addition to the unchanged caller prebound. There is
        // no credit for the old map or for omitted payload clones.
        fn node<V>() -> usize {
            crate::cleanup_plan::replay_btree_node_upper::<DeclarationId, V>()
                .expect("fixed nominal map layout")
        }
        for declaration in program.types().iter().chain(prelude) {
            reserve(node::<NominalPayload<ResolvedTypeParameterDeclaration>>())?;
            match &declaration.kind {
                TypeDeclarationKind::Record { .. } | TypeDeclarationKind::Class { .. } => {
                    reserve(node::<NominalPayload<ResolvedFieldDeclaration>>())?;
                }
                TypeDeclarationKind::Variant { cases } => {
                    reserve(node::<NominalPayload<ResolvedVariantCaseDeclaration>>())?;
                    for _ in cases {
                        reserve(node::<CaseFields>())?;
                    }
                }
                TypeDeclarationKind::Resource { .. } => {}
            }
        }
        for _ in program.functions() {
            reserve(node::<NominalPayload<ResolvedTypeParameterDeclaration>>())?;
        }
        for declaration in program.types() {
            if let TypeDeclarationKind::Class { methods, .. } = &declaration.kind {
                // The complete old producer rebuilds this class field entry.
                reserve(node::<NominalPayload<ResolvedFieldDeclaration>>())?;
                for _ in methods {
                    reserve(node::<NominalPayload<ResolvedTypeParameterDeclaration>>())?;
                }
            }
        }
        // Source types resolve shape-for-shape (parameters become scalar
        // metadata leaves); inherited fields reuse those same type shapes.
        // Traverse every declared field, not a nominal/prelude name filter.
        let mut capacity = 0;
        for declaration in program.types().iter().chain(prelude) {
            match &declaration.kind {
                TypeDeclarationKind::Record { fields }
                | TypeDeclarationKind::Class { fields, .. } => {
                    for field in fields {
                        capacity = capacity.max(frontier(&field.ty, reserve)?);
                    }
                }
                TypeDeclarationKind::Variant { cases } => {
                    for case in cases {
                        for field in &case.fields {
                            capacity = capacity.max(frontier(&field.ty, reserve)?);
                        }
                    }
                }
                TypeDeclarationKind::Resource { .. } => {}
            }
        }
        #[repr(C)]
        struct ArcCarrier<T> {
            strong: usize,
            weak: usize,
            value: T,
        }
        // At most one outer cases guard, one fields guard and one resolved
        // field type coexist. Price both initialization and receiving slots.
        let guards = 2 * size_of::<PendingVec<ResolvedVariantCaseDeclaration>>()
            + 2 * size_of::<PendingVec<ResolvedFieldDeclaration>>()
            + 2 * size_of::<PendingType>()
            + 2 * size_of::<PendingTypes>()
            + 2 * size_of::<ResolvedFieldDeclaration>()
            + 2 * size_of::<ResolvedVariantCaseDeclaration>()
            + 2 * size_of::<ResolvedType>();
        // The pthread std Mutex stores its native object in a lazy Box.
        // Fund that exact native Layout before its first lock, then initialize
        // it here so rollback never performs that allocation after refusal.
        #[cfg(all(
            unix,
            not(any(
                target_os = "linux",
                target_os = "android",
                target_os = "freebsd",
