            DeclarationId,
            Vec<ResolvedTypeParameterDeclaration>,
        >()
        .and_then(|n| n.checked_add(crate::prelude::OPTION_ID.len()))
        .and_then(|n| n.checked_add(std::mem::size_of::<ResolvedTypeParameterDeclaration>() + 1))
        .ok_or_else(fail)?;
