#[cfg(test)]
fn source_pass<E>(
    program: &dyn ProgramSource,
    reuse: Option<FunctionReuse<'_>>,
    reserve: &mut impl FnMut(usize) -> Result<(), E>,
) -> Result<(ResolvedProgram, FunctionResolutionWork), Failure<E>> {
