//! Existing byte-reservation seam for returned HIR headers. Full source/type
//! authentication remains at the resolver root; an ID miss substitutes nothing.
use super::*;

impl BasePreludeBundle {
    pub(crate) fn materialize_type<E>(
        &self,
        id: &DeclarationId,
        mut reserve: impl FnMut(usize) -> Result<(), E>,
    ) -> Result<Option<ResolvedTypeDeclaration>, E> {
        let Some(ty) = self.types_slice().iter().find(|ty| ty.id == *id) else {
            return Ok(None);
        };
        // Only names get new heap backing. All nominal sequences and IDs
        // reference their already-funded immutable owners. Include separately
        // live initialization, optional and receiving result carriers.
        let bytes = ty
            .name
            .len()
            .checked_add(std::mem::size_of::<String>())
            .and_then(|n| n.checked_add(std::mem::size_of::<ResolvedTypeDeclaration>()))
            .and_then(|n| n.checked_add(std::mem::size_of::<Option<ResolvedTypeDeclaration>>()))
            .and_then(|n| {
                n.checked_add(std::mem::size_of::<
                    Result<Option<ResolvedTypeDeclaration>, E>,
                >())
            })
            .expect("fixed base type materialization has addressable layouts");
        reserve(bytes)?;
        let mut name = String::with_capacity(ty.name.len());
        assert_eq!(
            name.capacity(),
            ty.name.len(),
            "exact base type name backing"
        );
        name.push_str(&ty.name);
        let ResolvedTypeDeclarationKind::Variant { cases } = &ty.kind else {
            unreachable!("immutable base schema only publishes variants");
        };
        Ok(Some(ResolvedTypeDeclaration {
            id: ty.id.clone(),
            name,
            type_parameters: ty.type_parameters.clone(),
            kind: ResolvedTypeDeclarationKind::Variant {
                cases: cases.clone(),
            },
            span: ty.span,
        }))
    }
}

//! Logical exports for Index roots and codecs. These infallible borrowed
//! adapters create no allocation or work allowance. Both inputs must already
//! follow the same canonical key order; duplicate keys retain the base value.
use super::*;

pub(crate) fn merge_by_key<'a, K: Ord + ?Sized + 'a, V: ?Sized + 'a>(
    base: impl Iterator<Item = (&'a K, &'a V)> + 'a,
    local: impl Iterator<Item = (&'a K, &'a V)> + 'a,
) -> impl Iterator<Item = (&'a K, &'a V)> + 'a {
    let mut base = base.peekable();
    let mut local = local.peekable();
    std::iter::from_fn(move || match (base.peek(), local.peek()) {
        (Some((a, _)), Some((b, _))) => match a.cmp(b) {
            std::cmp::Ordering::Less => base.next(),
            std::cmp::Ordering::Greater => local.next(),
            std::cmp::Ordering::Equal => {
                local.next();
                base.next()
            }
        },
        (Some(_), None) => base.next(),
        (None, Some(_)) => local.next(),
        (None, None) => None,
    })
}

struct Exact<I> {
    inner: I,
    remaining: usize,
}
impl<I: Iterator> Iterator for Exact<I> {
    type Item = I::Item;
    fn next(&mut self) -> Option<Self::Item> {
        let value = self.inner.next();
        if value.is_some() {
            self.remaining -= 1;
        }
        value
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}
impl<I: Iterator> ExactSizeIterator for Exact<I> {}

impl BasePreludeBundle {
    pub(crate) fn declaration_iteration<'a>(
        &'a self,
        local: &'a crate::hir::DeclarationIndex,
    ) -> impl ExactSizeIterator<Item = &'a Declaration> + 'a {
        let remaining = local
            .declarations
            .len()
            .checked_add(
                self.declarations_slice()
                    .iter()
                    .filter(|entry| !local.declarations.contains_key(&entry.id))
                    .count(),
            )
            .expect("held declaration inventories have addressable length");
        Exact {
            remaining,
            inner: merge_by_key(
                self.declarations_slice()
                    .iter()
                    .map(|entry| (&entry.id, entry)),
                local.declarations.iter(),
            )
            .map(|(_, value)| value),
        }
    }
}

//! Complete independent pre-schema base constructors and exact helper bodies.
use crate::ast::{
    FieldDeclaration, Span, Type, TypeDeclaration, TypeDeclarationKind, TypeParameterDeclaration,
    VariantCaseDeclaration,
};
use crate::prelude::{
    OPTION_ID, OPTION_NONE_ID, OPTION_SOME_ID, OPTION_SOME_VALUE_ID, RESULT_ERR_ERROR_ID,
    RESULT_ERR_ID, RESULT_ID, RESULT_OK_ID, RESULT_OK_VALUE_ID,
};
fn parameter(name: &str) -> TypeParameterDeclaration {
    TypeParameterDeclaration {
        name: name.to_owned(),
        span: Span::default(),
    }
}

fn parameter_type(name: &str) -> Type {
    Type::Named {
        name: name.to_owned(),
        arguments: Vec::new(),
    }
}

fn field(id: &str, name: &str, ty: Type) -> FieldDeclaration {
    FieldDeclaration {
        stable_id: id.to_owned(),
        explicit_id: true,
        name: name.to_owned(),
        name_span: Span::default(),
        ty,
        span: Span::default(),
    }
}

fn case(id: &str, name: &str, fields: Vec<FieldDeclaration>) -> VariantCaseDeclaration {
    VariantCaseDeclaration {
        stable_id: id.to_owned(),
        explicit_id: true,
        name: name.to_owned(),
        name_span: Span::default(),
        fields,
        span: Span::default(),
    }
}

pub(super) fn option() -> TypeDeclaration {
    TypeDeclaration {
        stable_id: OPTION_ID.to_owned(),
        explicit_id: true,
        name: "Option".to_owned(),
        name_span: Span::default(),
        type_parameters: vec![parameter("T")],
        kind: TypeDeclarationKind::Variant {
            cases: vec![
                case(OPTION_NONE_ID, "None", Vec::new()),
                case(
                    OPTION_SOME_ID,
                    "Some",
                    vec![field(OPTION_SOME_VALUE_ID, "value", parameter_type("T"))],
                ),
            ],
        },
        extends: None,
        invariants: None,
        span: Span::default(),
    }
}

pub(super) fn result() -> TypeDeclaration {
    TypeDeclaration {
        stable_id: RESULT_ID.to_owned(),
        explicit_id: true,
        name: "Result".to_owned(),
        name_span: Span::default(),
        type_parameters: vec![parameter("T"), parameter("E")],
        kind: TypeDeclarationKind::Variant {
            cases: vec![
                case(
                    RESULT_OK_ID,
                    "Ok",
                    vec![field(RESULT_OK_VALUE_ID, "value", parameter_type("T"))],
                ),
                case(
                    RESULT_ERR_ID,
                    "Err",
                    vec![field(RESULT_ERR_ERROR_ID, "error", parameter_type("E"))],
                ),
            ],
        },
        extends: None,
        invariants: None,
        span: Span::default(),
    }
}

//! Borrowed lookup overlay; it creates no merged BTreeMap or hidden owned HIR.
use super::*;
use crate::hir::{DeclarationIndex, ResolvedVariantCaseDeclaration};
use std::collections::btree_map::Values;
use std::iter::Peekable;

pub(crate) struct Overlay<'a> {
    base: &'a BasePreludeBundle,
    local: &'a DeclarationIndex,
}
impl<'a> Overlay<'a> {
    pub(super) fn new(base: &'a BasePreludeBundle, local: &'a DeclarationIndex) -> Self {
        Self { base, local }
    }
    pub(crate) fn declaration<P: Payer>(
        &self,
        id: &DeclarationId,
        payer: &mut P,
    ) -> Result<Option<&'a Declaration>, Failure<P::Error>> {
        if let Some(found) = self.base.declaration(id.as_str(), payer)? {
            return Ok(Some(found));
        }
        for declaration in self.local.declarations.values() {
            compare(declaration.id.as_str(), id.as_str(), payer)?;
            if declaration.id == *id {
                return Ok(Some(declaration));
            }
        }
        Ok(None)
    }
    pub(crate) fn type_id<P: Payer>(
        &self,
        name: &str,
        payer: &mut P,
    ) -> Result<Option<&'a DeclarationId>, Failure<P::Error>> {
        for ty in self.base.types() {
            compare(&ty.name, name, payer)?;
            if ty.name == name {
                return Ok(Some(&ty.id));
            }
        }
        for (candidate, id) in &self.local.types_by_name {
            compare(candidate, name, payer)?;
            if candidate == name {
                return Ok(Some(id));
            }
        }
        Ok(None)
    }
    fn named<P: Payer>(
        &self,
        owner: &DeclarationId,
        name: &str,
        kind: DeclarationKind,
        payer: &mut P,
    ) -> Result<Option<&'a DeclarationId>, Failure<P::Error>> {
        for declaration in self.base.declarations() {
            payer.work(1).map_err(Failure::Payer)?;
            if declaration.kind != kind {
                continue;
            }
            if let Some(candidate) = &declaration.owner {
                compare(candidate.as_str(), owner.as_str(), payer)?;
                compare(&declaration.name, name, payer)?;
                if candidate == owner && declaration.name == name {
                    return Ok(Some(&declaration.id));
                }
            }
        }
        let local = if kind == DeclarationKind::VariantCase {
            &self.local.cases_by_owner_name
        } else {
            &self.local.fields_by_owner_name
        };
        for ((candidate, candidate_name), id) in local {
            compare(candidate.as_str(), owner.as_str(), payer)?;
            compare(candidate_name, name, payer)?;
            if candidate == owner && candidate_name == name {
                return Ok(Some(id));
            }
        }
        Ok(None)
    }
    pub(crate) fn case_id<P: Payer>(
        &self,
        owner: &DeclarationId,
        name: &str,
        payer: &mut P,
    ) -> Result<Option<&'a DeclarationId>, Failure<P::Error>> {
        self.named(owner, name, DeclarationKind::VariantCase, payer)
    }
    pub(crate) fn field_id<P: Payer>(
        &self,
        owner: &DeclarationId,
        name: &str,
        payer: &mut P,
    ) -> Result<Option<&'a DeclarationId>, Failure<P::Error>> {
        self.named(owner, name, DeclarationKind::CaseField, payer)
    }
    pub(crate) fn type_parameters<P: Payer>(
        &self,
        owner: &DeclarationId,
        payer: &mut P,
    ) -> Result<Option<&'a [ResolvedTypeParameterDeclaration]>, Failure<P::Error>> {
        for ty in self.base.types() {
            compare(ty.id.as_str(), owner.as_str(), payer)?;
            if ty.id == *owner {
                return Ok(Some(ty.type_parameters.as_slice()));
            }
        }
        for (id, parameters) in &self.local.type_parameters {
            compare(id.as_str(), owner.as_str(), payer)?;
            if id == owner {
                return Ok(Some(parameters.as_slice()));
            }
        }
        Ok(None)
    }
    pub(crate) fn variant_cases<P: Payer>(
        &self,
        owner: &DeclarationId,
        payer: &mut P,
    ) -> Result<Option<&'a [ResolvedVariantCaseDeclaration]>, Failure<P::Error>> {
        for ty in self.base.types() {
            compare(ty.id.as_str(), owner.as_str(), payer)?;
            if ty.id == *owner {
                let ResolvedTypeDeclarationKind::Variant { cases } = &ty.kind else {
                    return Err(Failure::Schema);
                };
                return Ok(Some(cases.as_slice()));
            }
        }
        for (id, cases) in &self.local.variant_cases {
            compare(id.as_str(), owner.as_str(), payer)?;
            if id == owner {
                return Ok(Some(cases.as_slice()));
            }
        }
        Ok(None)
    }
    pub(crate) fn case_fields<P: Payer>(
        &self,
        owner: &DeclarationId,
        payer: &mut P,
    ) -> Result<Option<&'a [ResolvedFieldDeclaration]>, Failure<P::Error>> {
        for ty in self.base.types() {
            let ResolvedTypeDeclarationKind::Variant { cases } = &ty.kind else {
                return Err(Failure::Schema);
            };
            for case in cases.iter() {
                compare(case.id.as_str(), owner.as_str(), payer)?;
                if case.id == *owner {
                    return Ok(Some(&case.fields));
                }
            }
        }
        // The local index keeps its own canonical coordinate validation. Charge
        // its complete key comparison bound before invoking that unchanged API.
        for id in self.local.case_fields.keys() {
            compare(id.as_str(), owner.as_str(), payer)?;
        }
        Ok(self.local.case_fields(owner))
    }
    pub(crate) fn declarations<'p, P: Payer>(&self, payer: &'p mut P) -> Declarations<'a, 'p, P> {
        Declarations {
            base: self.base.declarations(),
            local: self.local.declarations.values().peekable(),
            payer,
            failed: false,
        }
    }
}

fn compare<P: Payer>(left: &str, right: &str, payer: &mut P) -> Result<(), Failure<P::Error>> {
    payer
        .work(
            left.len()
                .checked_add(right.len())
                .ok_or(Failure::Layout)?
                .checked_add(1)
                .ok_or(Failure::Layout)?,
        )
        .map_err(Failure::Payer)
}

pub(crate) struct Declarations<'a, 'p, P: Payer> {
    base: &'a [Declaration],
    local: Peekable<Values<'a, DeclarationId, Declaration>>,
    payer: &'p mut P,
    failed: bool,
}
impl<'a, P: Payer> Iterator for Declarations<'a, '_, P> {
    type Item = Result<&'a Declaration, Failure<P::Error>>;
    fn next(&mut self) -> Option<Self::Item> {
        if self.failed {
            return None;
        }
        let base = self.base.first();
        let local = self.local.peek().copied();
        let result = match (base, local) {
            (None, None) => return None,
            (Some(base), Some(local)) => {
                if let Err(error) = compare(base.id.as_str(), local.id.as_str(), self.payer) {
                    self.failed = true;
                    return Some(Err(error));
                }
                match base.id.cmp(&local.id) {
                    std::cmp::Ordering::Greater => self.local.next().unwrap(),
                    std::cmp::Ordering::Equal => {
                        self.local.next();
                        self.base = &self.base[1..];
                        base
                    }
                    std::cmp::Ordering::Less => {
                        self.base = &self.base[1..];
                        base
                    }
                }
            }
            (Some(base), None) => {
                if let Err(error) = self.payer.work(1) {
                    self.failed = true;
                    return Some(Err(Failure::Payer(error)));
                }
                self.base = &self.base[1..];
                base
            }
            (None, Some(_)) => {
                if let Err(error) = self.payer.work(1) {
                    self.failed = true;
                    return Some(Err(Failure::Payer(error)));
                }
                self.local.next().unwrap()
            }
        };
        Some(Ok(result))
    }
}

//! Explicit invocation acquisition. No ambient ledger or diagnostic construction.
use super::{Failure, Payer};
use crate::hir::DeclarationId;
use std::alloc::Layout;

pub(super) fn vector<T, P: Payer>(
    count: usize,
    payer: &mut P,
) -> Result<Vec<T>, Failure<P::Error>> {
    let layout = Layout::array::<T>(count).map_err(|_| Failure::Layout)?;
    payer.bytes(layout.size()).map_err(Failure::Payer)?;
    let mut values = Vec::new();
    values
        .try_reserve_exact(count)
        .map_err(|_| Failure::Allocation)?;
    // No downstream growth or allocator capacity repair may become unpaid.
    if values.capacity() != count && std::mem::size_of::<T>() != 0 {
        return Err(Failure::Capacity);
    }
    Ok(values)
}

pub(super) fn string<P: Payer>(text: &str, payer: &mut P) -> Result<String, Failure<P::Error>> {
    payer.work(text.len()).map_err(Failure::Payer)?;
    let mut bytes = vector::<u8, _>(text.len(), payer)?;
    bytes.extend_from_slice(text.as_bytes());
    payer.work(text.len()).map_err(Failure::Payer)?;
    String::from_utf8(bytes).map_err(|_| Failure::Schema)
}

pub(super) fn identity<P: Payer>(
    text: &str,
    payer: &mut P,
) -> Result<DeclarationId, Failure<P::Error>> {
    payer.work(text.len()).map_err(Failure::Payer)?;
    DeclarationId::paid_borrowed(text, |bytes| payer.bytes(bytes)).map_err(Failure::Payer)
}

pub(super) fn shared_bytes<T>() -> usize {
    #[repr(C)]
    struct Carrier<T> {
        strong: usize,
        weak: usize,
        value: T,
    }
    Layout::new::<Carrier<T>>().size()
}

//! Schema-driven base producer. Every Vec/String/identity/shared owner is paid
//! before construction; partial refusal drops staged owners without publication.
use super::*;

fn count() -> Option<usize> {
    BASE.iter().try_fold(BASE.len(), |count, schema| {
        schema.cases.iter().try_fold(count, |count, case| {
            count.checked_add(1)?.checked_add(case.fields.len())
        })
    })
}

fn descriptor<P: Payer>(
    text: &str,
    name: &str,
    kind: DeclarationKind,
    owner: Option<DeclarationId>,
    payer: &mut P,
) -> Result<Declaration, Failure<P::Error>> {
    Ok(Declaration {
        id: paid::identity(text, payer)?,
        name: paid::string(name, payer)?,
        kind,
        identity_origin: IdentityOrigin::CompilerOwned,
        owner,
    })
}

fn find<P: Payer>(
    declarations: &[Declaration],
    text: &str,
    payer: &mut P,
) -> Result<DeclarationId, Failure<P::Error>> {
    for declaration in declarations {
        payer
            .work(
                declaration
                    .id
                    .as_str()
                    .len()
                    .checked_add(text.len())
                    .ok_or(Failure::Layout)?,
            )
            .map_err(Failure::Payer)?;
        if declaration.id.as_str() == text {
            return Ok(declaration.id.clone());
        }
    }
    Err(Failure::Schema)
}

fn nominal<P: Payer>(
    schema: &Variant,
    declarations: &[Declaration],
    payer: &mut P,
) -> Result<ResolvedTypeDeclaration, Failure<P::Error>> {
    let owner = find(declarations, schema.id, payer)?;
    let mut parameters = paid::vector(schema.parameters.len(), payer)?;
    for (index, name) in schema.parameters.iter().enumerate() {
        payer.work(1).map_err(Failure::Payer)?;
        parameters.push(ResolvedTypeParameterDeclaration {
            name: paid::string(name, payer)?,
            index: u32::try_from(index).map_err(|_| Failure::Schema)?,
            span: Span::default(),
        });
    }
    let parameters = NominalPayload::from_funded_vec(&mut parameters, |n| payer.bytes(n))
        .map_err(Failure::Payer)?;
    let mut cases = paid::vector(schema.cases.len(), payer)?;
    for (index, case) in schema.cases.iter().enumerate() {
        let mut fields = paid::vector(case.fields.len(), payer)?;
        for (index, field) in case.fields.iter().enumerate() {
            let mut parameter = None;
            for (ordinal, name) in schema.parameters.iter().enumerate() {
                payer
                    .work(
                        name.len()
                            .checked_add(field.parameter.len())
                            .ok_or(Failure::Layout)?,
                    )
                    .map_err(Failure::Payer)?;
                if *name == field.parameter {
                    parameter = Some(u32::try_from(ordinal).map_err(|_| Failure::Schema)?);
                    break;
                }
            }
            fields.push(ResolvedFieldDeclaration {
                id: find(declarations, field.id, payer)?,
                name: paid::string(field.name, payer)?,
                index: u32::try_from(index).map_err(|_| Failure::Schema)?,
                ty: ResolvedType::TypeParameter {
                    owner: owner.clone(),
                    index: parameter.ok_or(Failure::Schema)?,
                },
                span: Span::default(),
            });
        }
        cases.push(ResolvedVariantCaseDeclaration {
            id: find(declarations, case.id, payer)?,
            name: paid::string(case.name, payer)?,
            index: u32::try_from(index).map_err(|_| Failure::Schema)?,
            fields,
            span: Span::default(),
        });
    }
    let cases =
        NominalPayload::from_funded_vec(&mut cases, |n| payer.bytes(n)).map_err(Failure::Payer)?;
    Ok(ResolvedTypeDeclaration {
        id: owner,
        name: paid::string(schema.name, payer)?,
        type_parameters: parameters,
        kind: ResolvedTypeDeclarationKind::Variant { cases },
        span: Span::default(),
    })
}

pub(super) fn contents<P: Payer>(payer: &mut P) -> Result<Contents, Failure<P::Error>> {
    payer.work(1).map_err(Failure::Payer)?;
    let mut declarations = paid::vector(count().ok_or(Failure::Layout)?, payer)?;
    for schema in BASE {
        let top = descriptor(
            schema.id,
            schema.name,
            DeclarationKind::Variant,
            None,
            payer,
        )?;
        let owner = top.id.clone();
        declarations.push(top);
        for case in schema.cases {
            let child = descriptor(
                case.id,
                case.name,
                DeclarationKind::VariantCase,
                Some(owner.clone()),
                payer,
            )?;
            let case_owner = child.id.clone();
            declarations.push(child);
            for field in case.fields {
                declarations.push(descriptor(
                    field.id,
                    field.name,
                    DeclarationKind::CaseField,
                    Some(case_owner.clone()),
                    payer,
                )?);
            }
        }
    }
    // Fallible insertion sort performs no hidden allocation and charges each
    // actual key comparison before reading its bytes. IDs must remain unique.
    for i in 1..declarations.len() {
        let mut j = i;
        while j > 0 {
            payer
                .work(
                    declarations[j - 1]
                        .id
                        .as_str()
                        .len()
                        .checked_add(declarations[j].id.as_str().len())
                        .ok_or(Failure::Layout)?,
                )
                .map_err(Failure::Payer)?;
            match declarations[j - 1].id.cmp(&declarations[j].id) {
                std::cmp::Ordering::Equal => return Err(Failure::Schema),
                std::cmp::Ordering::Less => break,
                std::cmp::Ordering::Greater => declarations.swap(j - 1, j),
            }
            j -= 1;
        }
    }
    let mut types = paid::vector(BASE.len(), payer)?;
    for schema in BASE {
        types.push(nominal(schema, &declarations, payer)?);
    }
    Ok(Contents {
        declarations,
        types,
    })
}

use super::{BasePreludeBundle, Failure, Payer};
use crate::hir::{DeclarationId, DeclarationIndex, ResolvedTypeDeclarationKind};
use crate::test_allocation_observer::measure;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Denied {
    Bytes,
    Work,
    Site,
}
struct Account {
    bytes: usize,
    work: usize,
    byte_limit: usize,
    work_limit: usize,
    sites: usize,
    fail_site: Option<usize>,
    first: Option<Denied>,
}
impl Account {
    fn unlimited() -> Self {
        Self {
            bytes: 0,
            work: 0,
            byte_limit: usize::MAX,
            work_limit: usize::MAX,
            sites: 0,
            fail_site: None,
            first: None,
        }
    }
    fn deny(&mut self, error: Denied) -> Result<(), Denied> {
        Err(*self.first.get_or_insert(error))
    }
}
impl Payer for Account {
    type Error = Denied;
    fn bytes(&mut self, requested: usize) -> Result<(), Denied> {
        if let Some(first) = self.first {
            return Err(first);
        }
        if requested > 0 {
            self.sites += 1;
            if self.fail_site == Some(self.sites) {
                return self.deny(Denied::Site);
            }
        }
        if requested > self.byte_limit - self.bytes {
            return self.deny(Denied::Bytes);
        }
        self.bytes += requested;
        Ok(())
    }
    fn work(&mut self, requested: usize) -> Result<(), Denied> {
        if let Some(first) = self.first {
            return Err(first);
        }
        if requested > self.work_limit - self.work {
            return self.deny(Denied::Work);
        }
        self.work += requested;
        Ok(())
    }
}
fn program() -> crate::ast::Program {
    crate::parse(
        "module prelude.bundle; @id(\"bundle.main\") fn main()->i64 {0}",
        "bundle.spx",
    )
    .unwrap()
}

#[test]
fn complete_original_base_types_and_every_lookup_keep_exact_order_ids_and_payloads() {
    let program = program();
    let original = [super::original::option(), super::original::result()];
    let original_index =
        DeclarationIndex::nominal_original_with_prelude(&program, &original).unwrap();
    let resolved = crate::hir::resolve(&program).unwrap();
    let local = DeclarationIndex::from_verified_with_prelude(&program, &[]).unwrap();
    let mut payer = Account::unlimited();
    let bundle = BasePreludeBundle::acquire(&mut payer).unwrap();
    assert_eq!(bundle.types(), resolved.types.as_slice());
    assert_eq!(bundle.types()[0].id.as_str(), crate::prelude::OPTION_ID);
    assert_eq!(bundle.types()[1].id.as_str(), crate::prelude::RESULT_ID);
    let overlay = bundle.overlay(&local);
    let all = overlay
        .declarations(&mut payer)
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    assert_eq!(all, original_index.declarations().collect::<Vec<_>>());
    for declaration in original_index.declarations() {
        assert_eq!(
            overlay.declaration(&declaration.id, &mut payer).unwrap(),
            Some(declaration)
        );
        assert_eq!(
            overlay
                .type_parameters(&declaration.id, &mut payer)
                .unwrap(),
            original_index.type_parameters(&declaration.id)
        );
    }
    for ty in bundle.types() {
        assert_eq!(
            overlay.type_id(&ty.name, &mut payer).unwrap(),
            original_index.type_id(&ty.name)
        );
        assert_eq!(
            overlay.variant_cases(&ty.id, &mut payer).unwrap(),
            original_index.variant_cases(&ty.id)
        );
        let ResolvedTypeDeclarationKind::Variant { cases } = &ty.kind else {
            panic!("base variant");
        };
        for case in cases.iter() {
            assert_eq!(
                overlay.case_id(&ty.id, &case.name, &mut payer).unwrap(),
                original_index.case_id(&ty.id, &case.name)
            );
            assert_eq!(
                overlay.case_fields(&case.id, &mut payer).unwrap(),
                original_index.case_fields(&case.id)
            );
            for field in &case.fields {
                assert_eq!(
                    overlay.field_id(&case.id, &field.name, &mut payer).unwrap(),
                    original_index.field_id(&case.id, &field.name)
                );
            }
        }
    }
    let foreign = DeclarationId::new("foreign.bundle");
    assert!(overlay.declaration(&foreign, &mut payer).unwrap().is_none());
    assert!(overlay.case_fields(&foreign, &mut payer).unwrap().is_none());
    assert!(overlay
        .variant_cases(&foreign, &mut payer)
        .unwrap()
        .is_none());
    assert!(overlay.type_id("Foreign", &mut payer).unwrap().is_none());
}

#[test]
fn two_borrowed_module_overlays_and_explicit_lease_share_actual_payload_addresses() {
    let local_a = DeclarationIndex::from_verified_with_prelude(&program(), &[]).unwrap();
    let local_b = DeclarationIndex::from_verified_with_prelude(&program(), &[]).unwrap();
    let id = DeclarationId::new(crate::prelude::OPTION_SOME_ID);
    let mut payer = Account::unlimited();
    let bundle = BasePreludeBundle::acquire(&mut payer).unwrap();
    let before = payer.bytes;
    let (lease, allocation) = measure(|| {
        let lease = bundle.retain(&mut payer).unwrap();
        let a = bundle.overlay(&local_a);
        let b = lease.overlay(&local_b);
        assert!(std::ptr::eq(
            a.declaration(&id, &mut payer).unwrap().unwrap(),
            b.declaration(&id, &mut payer).unwrap().unwrap()
        ));
        assert_eq!(
            a.case_fields(&id, &mut payer).unwrap().unwrap().as_ptr(),
            b.case_fields(&id, &mut payer).unwrap().unwrap().as_ptr()
        );
        lease
    });
    assert_eq!(payer.bytes, before);
    assert!(!allocation.invalid);
    assert_eq!(allocation.allocated, 0);
    assert_eq!(bundle.types().as_ptr(), lease.types().as_ptr());
    drop(bundle);
    assert_eq!(lease.types().len(), 2);
    drop(lease);
    // Observe the last retained owner, not only the original bundle's Drop.
    let mut retained_account = Account::unlimited();
    let (_, retained_drop) = measure(|| {
        let original = BasePreludeBundle::acquire(&mut retained_account).unwrap();
        let retained = original.retain(&mut retained_account).unwrap();
        let compatibility = retained.clone();
        assert_eq!(
            compatibility.types_slice().as_ptr(),
            retained.types_slice().as_ptr()
        );
        drop(original);
        drop(retained);
        assert_eq!(compatibility.types_slice().len(), 2);
        drop(compatibility);
    });
    assert!(!retained_drop.invalid);
    assert_eq!(retained_drop.live, 0);
    assert_eq!(retained_drop.allocated, retained_drop.freed);
    assert!(retained_drop.highwater <= retained_account.bytes);
}

#[test]
fn whole_owner_exact_one_short_zero_work_and_each_acquisition_refusal_drop_every_owner() {
    let mut baseline = Account::unlimited();
    let (_, observed) = measure(|| drop(BasePreludeBundle::acquire(&mut baseline).unwrap()));
    assert!(!observed.invalid);
    assert_eq!(observed.live, 0);
    assert_eq!(observed.allocated, observed.freed);
    assert!(observed.allocated <= baseline.bytes);
    assert!(observed.highwater <= baseline.bytes);
    for (bytes, work, succeeds) in [
        (baseline.bytes, baseline.work, true),
        (baseline.bytes - 1, baseline.work, false),
        (0, baseline.work, false),
        (baseline.bytes, baseline.work - 1, false),
        (baseline.bytes, 0, false),
    ] {
        let mut account = Account::unlimited();
        account.byte_limit = bytes;
        account.work_limit = work;
        let (_, allocation) = measure(|| {
            let result = BasePreludeBundle::acquire(&mut account);
            assert_eq!(result.is_ok(), succeeds);
            drop(result);
        });
        assert!(!allocation.invalid);
        assert_eq!(allocation.live, 0);
        assert_eq!(allocation.allocated, allocation.freed);
        assert!(allocation.allocated <= account.bytes);
        if !succeeds {
            let first = account.first.unwrap();
            let (_, after) = measure(|| {
                assert_eq!(
                    BasePreludeBundle::acquire(&mut account).err().unwrap(),
                    Failure::Payer(first)
                );
            });
            assert_eq!(after.allocated, 0);
            assert_eq!(account.first, Some(first));
        }
    }
    for site in 1..=baseline.sites {
        let mut account = Account::unlimited();
        account.fail_site = Some(site);
        let (_, allocation) = measure(|| {
            assert!(BasePreludeBundle::acquire(&mut account).is_err());
        });
        assert!(!allocation.invalid);
        assert_eq!(allocation.live, 0);
        assert_eq!(allocation.allocated, allocation.freed);
        assert_eq!(account.first, Some(Denied::Site));
    }
}

#[test]
fn lookup_iteration_and_lease_work_keep_the_same_sticky_invocation_account() {
    let local = DeclarationIndex::from_verified_with_prelude(&program(), &[]).unwrap();
    let mut payer = Account::unlimited();
    let bundle = BasePreludeBundle::acquire(&mut payer).unwrap();
    let id = DeclarationId::new(crate::prelude::RESULT_ID);
    let start = payer.work;
    let result = bundle.overlay(&local).declaration(&id, &mut payer).unwrap();
    assert!(result.is_some());
    let cost = payer.work - start;
    payer.work_limit = payer.work + cost;
    assert!(bundle
        .overlay(&local)
        .declaration(&id, &mut payer)
        .unwrap()
        .is_some());
    let (_, allocation) = measure(|| {
        assert_eq!(
            bundle
                .overlay(&local)
                .declaration(&id, &mut payer)
                .err()
                .unwrap(),
            Failure::Payer(Denied::Work)
        );
        assert_eq!(
            bundle.retain(&mut payer).err().unwrap(),
            Failure::Payer(Denied::Work)
        );
        let overlay = bundle.overlay(&local);
        let mut values = overlay.declarations(&mut payer);
        assert_eq!(
            values.next().unwrap().err().unwrap(),
            Failure::Payer(Denied::Work)
        );
        assert!(values.next().is_none());
    });
    assert!(!allocation.invalid);
    assert_eq!(allocation.allocated, 0);
}

#[test]
fn unused_and_parser_only_overlapping_names_keep_unconditional_base_selection() {
    // These overlap inputs are parser/index controls only. They grant no
    // resolution admission to source declarations shadowing compiler names.
    for declaration in [
        "",
