#[test]
fn fixed_schema_work_payer_covers_actual_producer_exactly_and_plus_one_is_sticky() {
    use super::{FixedFailure, FixedSchemaPayer, WorkRefusal};
    let mut owner = Account::unlimited();
    let (receipt, physical) = measure(|| {
        let mut reserve = |n| owner.bytes(n);
        let mut fixed = FixedSchemaPayer::acquire(&mut reserve).unwrap();
        let bundle = BasePreludeBundle::acquire(&mut fixed).unwrap();
        let exact = fixed.receipt();
        assert_eq!(exact.limit, super::work_model::REQUIRED);
        assert_eq!(exact.used, exact.limit);
        assert_eq!(exact.remaining, 0);
        assert_eq!(exact.first, None);
        let selected = WorkRefusal {
            requested: 1,
            remaining: 0,
        };
        assert_eq!(fixed.work(1), Err(FixedFailure::Work(selected)));
        assert_eq!(fixed.work(0), Err(FixedFailure::Work(selected)));
        assert_eq!(fixed.bytes(0), Err(FixedFailure::Work(selected)));
        assert_eq!(fixed.bytes(usize::MAX), Err(FixedFailure::Work(selected)));
        assert!(
            matches!(BasePreludeBundle::acquire(&mut fixed), Err(Failure::Payer(FixedFailure::Work(first))) if first == selected)
        );
        assert_eq!(fixed.receipt().first, Some(selected));
        assert_eq!(fixed.receipt().used, exact.used);
        drop(bundle);
        fixed.receipt()
    });
    assert!(receipt.first.is_some());
    assert_eq!(
        owner.work, 0,
        "no credit was borrowed from a generic work account"
    );
    assert_eq!(
        owner.first, None,
        "the fixed work owner records its own refusal"
    );
    assert!(!physical.invalid);
    assert_eq!(physical.live, 0);
    assert_eq!(physical.allocated, physical.freed);
    assert!(physical.allocated <= owner.bytes);
    assert!(physical.highwater <= owner.bytes);
    for limit in [super::work_model::REQUIRED - 1, 0] {
        let mut owner = Account::unlimited();
        let (_, physical) = measure(|| {
            let mut reserve = |n| owner.bytes(n);
            let mut fixed = FixedSchemaPayer::acquire(&mut reserve).unwrap();
            fixed.restrict_for_test(limit);
            assert!(matches!(
                BasePreludeBundle::acquire(&mut fixed),
                Err(Failure::Payer(FixedFailure::Work(_)))
            ));
            let first = fixed.receipt().first.unwrap();
            assert!(first.requested > first.remaining);
            assert_eq!(fixed.work(0), Err(FixedFailure::Work(first)));
            assert_eq!(fixed.bytes(0), Err(FixedFailure::Work(first)));
            assert_eq!(fixed.bytes(usize::MAX), Err(FixedFailure::Work(first)));
            assert!(
                matches!(BasePreludeBundle::acquire(&mut fixed), Err(Failure::Payer(FixedFailure::Work(retry))) if retry == first)
            );
            assert_eq!(fixed.receipt().first, Some(first));
        });
        assert!(!physical.invalid);
        assert_eq!(physical.live, 0);
        assert_eq!(physical.allocated, physical.freed);
        assert!(physical.allocated <= owner.bytes);
    }
}

#[test]
fn fixed_schema_counter_setup_and_byte_refusal_keep_exact_existing_owner_error() {
    use super::{FixedFailure, FixedSchemaPayer, WorkReceipt};
    let carriers = std::mem::size_of::<FixedSchemaPayer<'_, Denied>>()
        + std::mem::size_of::<Result<FixedSchemaPayer<'_, Denied>, Denied>>()
        + std::mem::size_of::<WorkReceipt>();
    for limit in [0, carriers - 1, carriers] {
        let mut owner = Account::unlimited();
        owner.byte_limit = limit;
        let (_, physical) = measure(|| {
            let mut reserve = |n| owner.bytes(n);
            let setup = FixedSchemaPayer::acquire(&mut reserve);
            if limit < carriers {
                assert!(matches!(setup, Err(Denied::Bytes)));
            } else {
                let mut fixed = setup.unwrap();
                assert_eq!(fixed.receipt().used, 0);
                assert!(matches!(
                    BasePreludeBundle::acquire(&mut fixed),
                    Err(Failure::Payer(FixedFailure::Bytes(Denied::Bytes)))
                ));
                // Byte failure wins even a request that would exhaust work.
                assert_eq!(
                    fixed.work(usize::MAX),
                    Err(FixedFailure::Bytes(Denied::Bytes))
                );
                assert_eq!(fixed.bytes(0), Err(FixedFailure::Bytes(Denied::Bytes)));
                assert_eq!(fixed.receipt().first, None);
                assert_eq!(fixed.receipt().used, 0);
            }
        });
        assert_eq!(owner.first, Some(Denied::Bytes));
        assert_eq!(owner.bytes, if limit == carriers { carriers } else { 0 });
        assert_eq!(physical.allocated, 0);
        assert_eq!(physical.live, 0);
        assert!(!physical.invalid);
    }
}

//! Compile-time work census over the sole fixed base schema. There is no
//! runtime census allocation, authored input, replay credit or guessed factor.
use crate::prelude::base_schema::BASE;

const fn count() -> usize {
    let mut total = BASE.len();
    let mut t = 0;
    while t < BASE.len() {
        let mut c = 0;
        while c < BASE[t].cases.len() {
            total += 1 + BASE[t].cases[c].fields.len();
            c += 1;
        }
        t += 1;
    }
    total
}
const COUNT: usize = count();
const fn order(a: &str, b: &str) -> i8 {
    let a = a.as_bytes();
    let b = b.as_bytes();
    let mut i = 0;
    while i < a.len() && i < b.len() {
        if a[i] < b[i] {
            return -1;
        }
        if a[i] > b[i] {
            return 1;
        }
        i += 1;
    }
    if a.len() < b.len() {
        -1
    } else if a.len() > b.len() {
        1
    } else {
        0
    }
}
const fn find(ids: &[&str; COUNT], text: &str) -> usize {
    let mut work = 0;
    let mut i = 0;
    while i < COUNT {
        work += ids[i].len() + text.len();
        if order(ids[i], text) == 0 {
            return work;
        }
        i += 1;
    }
    panic!("fixed base work model references an absent descriptor")
}
const fn required() -> usize {
    // contents entry, descriptor identities and two name-byte passes.
    let mut work = 1;
    let mut ids = [""; COUNT];
    let mut at = 0;
    let mut t = 0;
    while t < BASE.len() {
        let ty = BASE[t];
        ids[at] = ty.id;
        at += 1;
        work += ty.id.len() + 2 * ty.name.len();
        let mut c = 0;
        while c < ty.cases.len() {
            let case = &ty.cases[c];
            ids[at] = case.id;
            at += 1;
            work += case.id.len() + 2 * case.name.len();
            let mut f = 0;
            while f < case.fields.len() {
                let field = &case.fields[f];
                ids[at] = field.id;
                at += 1;
                work += field.id.len() + 2 * field.name.len();
                f += 1;
            }
            c += 1;
        }
        t += 1;
    }
    assert!(at == COUNT);
    // Exact insertion-sort key comparison sequence, with the same source order
    // and byte ordering as producer::contents. The census itself is const eval.
    let mut i = 1;
    while i < COUNT {
        let mut j = i;
        while j > 0 {
            work += ids[j - 1].len() + ids[j].len();
            let ordering = order(ids[j - 1], ids[j]);
            assert!(ordering != 0, "fixed base IDs must be unique");
            if ordering < 0 {
                break;
            }
            let previous = ids[j - 1];
            ids[j - 1] = ids[j];
            ids[j] = previous;
            j -= 1;
        }
        i += 1;
    }
    t = 0;
    while t < BASE.len() {
        let ty = BASE[t];
        work += find(&ids, ty.id) + 2 * ty.name.len();
        let mut p = 0;
        while p < ty.parameters.len() {
            work += 1 + 2 * ty.parameters[p].len();
            p += 1;
        }
        let mut c = 0;
        while c < ty.cases.len() {
            let case = &ty.cases[c];
            work += find(&ids, case.id) + 2 * case.name.len();
            let mut f = 0;
            while f < case.fields.len() {
                let field = &case.fields[f];
                work += find(&ids, field.id) + 2 * field.name.len();
                p = 0;
                let mut found = false;
                while p < ty.parameters.len() {
                    work += ty.parameters[p].len() + field.parameter.len();
                    if order(ty.parameters[p], field.parameter) == 0 {
                        found = true;
                        break;
                    }
                    p += 1;
                }
                assert!(found, "fixed base field must name a declared parameter");
                f += 1;
            }
            c += 1;
        }
        t += 1;
    }
    work
}
/// Logical units at the producer's existing explicit work sites, not CPU time.
pub(super) const REQUIRED: usize = required();

//! One paid current-index snapshot of borrowed entries, no declaration cloning.
use crate::cleanup_plan::renewal_profile::ordinary::{Admission, Refusal, Scratch};
use crate::hir::renewal_probes::{Index, Work};
use crate::hir::{DeclarationId, DeclarationIndex};
#[derive(Debug)]
pub(crate) struct Probes<'a> {
    declarations: Vec<(&'a DeclarationId, &'a crate::hir::Declaration)>,
    parameters: Vec<(
        &'a DeclarationId,
        &'a crate::hir::NominalPayload<crate::hir::ResolvedTypeParameterDeclaration>,
    )>,
    fields: Vec<(
        &'a DeclarationId,
        &'a crate::hir::NominalPayload<crate::hir::ResolvedFieldDeclaration>,
    )>,
}
fn collect<'a, V>(
    map: &'a std::collections::BTreeMap<DeclarationId, V>,
    admission: &mut Admission<'_>,
) -> Result<Vec<(&'a DeclarationId, &'a V)>, Refusal> {
    let mut entries = Scratch::new(admission)?;
    for (key, value) in map {
        admission.units(1)?;
        entries.push((key, value), admission)?;
    }
    Ok(entries.into_vec())
}
fn get<'a, V>(
    entries: &[(&'a DeclarationId, &'a V)],
    key: &DeclarationId,
    work: &mut Work<'_>,
) -> Result<Option<&'a V>, ()> {
    let (mut start, mut end) = (0, entries.len());
    while start < end {
        let mid = start + (end - start) / 2;
        let n = key
            .as_str()
            .len()
            .min(entries[mid].0.as_str().len())
            .checked_add(1)
            .ok_or(())?;
        crate::hir::renewal_probes::units(work, n)?;
        match entries[mid].0.cmp(key) {
            std::cmp::Ordering::Less => start = mid + 1,
            std::cmp::Ordering::Greater => end = mid,
            std::cmp::Ordering::Equal => return Ok(Some(entries[mid].1)),
        }
    }
    Ok(None)
}
impl<'a> Probes<'a> {
    pub(crate) fn new(
        index: &'a DeclarationIndex,
        admission: &mut Admission<'_>,
    ) -> Result<Self, Refusal> {
        admission.reserve(std::mem::size_of::<Self>())?;
        Ok(Self {
            declarations: collect(&index.declarations, admission)?,
            parameters: collect(&index.type_parameters, admission)?,
            fields: collect(&index.record_fields, admission)?,
        })
    }
}
#[cfg(test)]
impl Probes<'_> {
    pub(crate) fn backing_bytes(&self) -> usize {
        self.declarations.capacity()
            * std::mem::size_of::<(&DeclarationId, &crate::hir::Declaration)>()
            + self.parameters.capacity()
                * std::mem::size_of::<(
                    &DeclarationId,
                    &Vec<crate::hir::ResolvedTypeParameterDeclaration>,
                )>()
            + self.fields.capacity()
                * std::mem::size_of::<(&DeclarationId, &Vec<crate::hir::ResolvedFieldDeclaration>)>(
                )
    }
}
impl Index for Probes<'_> {
    fn declaration(
        &self,
        key: &DeclarationId,
        work: &mut Work<'_>,
    ) -> Result<Option<&crate::hir::Declaration>, ()> {
        get(&self.declarations, key, work)
    }
    fn parameters(
        &self,
        key: &DeclarationId,
        work: &mut Work<'_>,
    ) -> Result<Option<&Vec<crate::hir::ResolvedTypeParameterDeclaration>>, ()> {
        get(&self.parameters, key, work).map(|value| value.map(|v| &**v))
    }
    fn fields(
        &self,
        key: &DeclarationId,
        work: &mut Work<'_>,
    ) -> Result<Option<&Vec<crate::hir::ResolvedFieldDeclaration>>, ()> {
        get(&self.fields, key, work).map(|value| value.map(|v| &**v))
    }
}

