fn program(depth: usize) -> ResolvedProgram {
    let mut source = crate::hir::iterative_validator_tests::SOURCE.to_owned();
    for n in 0..depth {
        source.push_str(&format!("\n@id(\"inline.row.{n}\") record InlineRow{n} {{ @id(\"inline.row.{n}.value\") value:i64, }}\n"));
