        let item = program
            .types
            .iter_mut()
            .find(|item| item.id.as_str() == format!("inline.row.{n}"))
            .unwrap();
        let ResolvedTypeDeclarationKind::Record { fields } = &mut item.kind else {
            unreachable!()
        };
        fields[0].ty = root(&format!("inline.row.{}", n + 1));
