    set_parameter_type(&mut program, "classifier.take", root);

    let error = classify(&program, "classifier.take").unwrap_err();
    assert_eq!(error, Refusal::BoundExceeded);
    assert_eq!(error.code(), BOUND_EXCEEDED);
}

