fn many_fields_source(field_count: usize) -> String {
    assert!(field_count >= 1);
    let mut fields = String::new();
    for index in 0..field_count - 1 {
        fields.push_str(&format!(
            "    @id(\"classifier.big.f{index}\")\n    f{index}: i64,\n"
