        });
        assert_eq!(success, limit == expected);
        assert!(!observed.invalid);
        if success {
            assert_eq!(observed.allocated, requested);
        }
        assert!(observed.allocated <= limit - left.get());
        assert_eq!(observed.live, 0);
    }
