//! Exact acquisition operations for the actual canonical nominal constructor.
//! Legacy identity-only construction retains its independent unpriced helpers.
use super::*;
use std::mem::size_of;
mod types;
pub(super) enum Payer<'a, E> {
    Legacy(&'a mut dyn FnMut(&str) -> Result<DeclarationId, E>),
    Funded(&'a mut dyn FnMut(usize) -> Result<(), E>),
}
impl<E> Payer<'_, E> {
    pub(super) fn bytes(&mut self, bytes: usize) -> Result<(), E> {
        match self {
            Self::Legacy(_) => Ok(()),
            Self::Funded(reserve) => reserve(bytes),
        }
    }
    pub(super) fn identity(&mut self, text: &str) -> Result<DeclarationId, E> {
        match self {
            Self::Legacy(identity) => identity(text),
            Self::Funded(reserve) => {
                reserve(2 * size_of::<DeclarationId>() + size_of::<Result<DeclarationId, E>>())?;
                DeclarationId::paid_borrowed(text, reserve)
            }
        }
    }
    pub(super) fn text(&mut self, text: &str) -> Result<String, E> {
        self.bytes(
            (2 * size_of::<String>())
                .saturating_add(size_of::<Result<String, E>>())
                .saturating_add(text.len()),
        )?;
        Ok(text.to_owned())
    }
    pub(super) fn node<K, V>(&mut self) -> Result<(), E> {
        self.bytes(
            crate::cleanup_plan::replay_btree_node_upper::<K, V>()
                .expect("fixed constructor map layout"),
        )
    }
    pub(super) fn vector<T>(&mut self, len: usize) -> Result<(), E> {
        self.bytes(
            (2 * size_of::<Vec<T>>())
                .saturating_add(size_of::<Result<Vec<T>, E>>())
                .saturating_add(len.saturating_mul(size_of::<T>())),
        )
    }
    pub(super) fn vec<T>(&mut self, len: usize) -> Result<Vec<T>, E> {
        self.vector::<T>(len)?;
        let values = Vec::with_capacity(len);
        assert_eq!(values.capacity(), len);
        Ok(values)
    }
    pub(super) fn grow<T>(&mut self, values: &mut Vec<T>, additional: usize) -> Result<(), E> {
        if values.capacity() - values.len() >= additional {
            return Ok(());
        }
        let capacity = values
            .capacity()
            .saturating_mul(2)
            .max(values.len().saturating_add(additional))
            .max(4);
        let mut next = self.vec(capacity)?;
        next.append(values);
        *values = next;
        Ok(())
    }
    pub(super) fn top(&mut self, name: &str, kind: DeclarationKind) -> Result<(), E> {
        // Caller creates one name; insert_top_level clones the map key once.
        if matches!(
            kind,
            DeclarationKind::Resource
                | DeclarationKind::Record
                | DeclarationKind::Class
                | DeclarationKind::Variant
                | DeclarationKind::Function
        ) {
            self.bytes(size_of::<String>().saturating_add(name.len()))?;
            self.node::<String, DeclarationId>()?;
        }
        self.node::<DeclarationId, Declaration>()?;
        self.bytes(2 * size_of::<Declaration>())
    }
    pub(super) fn owned(&mut self) -> Result<(), E> {
        self.node::<DeclarationId, Declaration>()?;
        self.bytes(2 * size_of::<Declaration>())
    }
    pub(super) fn field(&mut self, name: &str) -> Result<(), E> {
        // One metadata name and its owner/name key; the original field/type
        // remains in the guarded canonical sequence and is never deep-cloned.
        self.bytes(2 * size_of::<String>() + 2 * name.len())?;
        self.node::<(DeclarationId, String), DeclarationId>()?;
        self.owned()
    }
    pub(super) fn case(&mut self, name: &str) -> Result<(), E> {
        self.bytes(size_of::<String>() + name.len())?;
        self.node::<(DeclarationId, String), DeclarationId>()?;
        self.owned()
    }
    pub(super) fn semantic(
        &mut self,
        code: &'static str,
        args: std::fmt::Arguments<'_>,
        span: Span,
        path: &str,
        legacy_logical_format: bool,
    ) -> super::identity_payer::IdentityIndexError<E> {
        use super::identity_payer::IdentityIndexError;
        match self {
            Self::Legacy(_) => {
                let message = if legacy_logical_format {
                    crate::bounded_output::budgeted_format(args)
                } else {
                    std::fmt::format(args)
                };
                IdentityIndexError::Semantic(Diagnostic::error(code, message, span).at_path(path))
            }
            Self::Funded(reserve) => {
                match super::nominal_paid_values::diagnostic(code, args, span, path, *reserve) {
                    Ok(diagnostic) => IdentityIndexError::Semantic(diagnostic),
                    Err(error) => error,
                }
            }
        }
    }
    pub(super) fn resolve_type(
        &mut self,
        index: &DeclarationIndex,
        ty: &Type,
        owner: Option<&DeclarationId>,
    ) -> Result<Option<ResolvedType>, E> {
        if matches!(self, Self::Legacy(_)) {
            return Ok(index.resolve_source_type(ty, owner));
        }
        types::resolve(index, ty, owner, self)
    }
}
impl DeclarationIndex {
    pub(super) fn insert_field_view(
        &mut self,
        owner: DeclarationId,
        field: &ResolvedFieldDeclaration,
        origin: IdentityOrigin,
    ) {
        self.fields_by_owner_name
            .insert((owner.clone(), field.name.clone()), field.id.clone());
        self.declarations.insert(
            field.id.clone(),
            Declaration {
                id: field.id.clone(),
                name: field.name.clone(),
                kind: DeclarationKind::Field,
                identity_origin: origin,
                owner: Some(owner),
            },
        );
    }
    pub(super) fn insert_case_field_view(
        &mut self,
        owner: DeclarationId,
        field: &ResolvedFieldDeclaration,
        origin: IdentityOrigin,
    ) {
        self.fields_by_owner_name
            .insert((owner.clone(), field.name.clone()), field.id.clone());
        self.declarations.insert(
            field.id.clone(),
            Declaration {
                id: field.id.clone(),
                name: field.name.clone(),
                kind: DeclarationKind::CaseField,
                identity_origin: origin,
                owner: Some(owner),
            },
        );
    }
}

//! Complete source type receiver with prepaid frames/results/arguments.
use super::*;
pub(super) fn resolve<E>(
    index: &DeclarationIndex,
    ty: &Type,
    owner: Option<&DeclarationId>,
    payer: &mut Payer<'_, E>,
) -> Result<Option<ResolvedType>, E> {
    enum Frame<'a> {
        Enter(&'a Type),
        Finish(DeclarationId, usize),
    }
    payer.bytes(2 * size_of::<Frame<'_>>() + size_of::<Result<Option<ResolvedType>, E>>())?;
    let mut frames = payer.vec(1)?;
    frames.push(Frame::Enter(ty));
    let mut resolved = index.nominal_drop_workspace.types();
    while let Some(frame) = frames.pop() {
        match frame {
            Frame::Enter(ty) => {
                let value = match ty {
                    Type::Function { parameters, result } => {
                        if parameters.len() > 8 {
                            return Ok(None);
                        }
                        // The independent receiver admits only direct scalar
                        // function parameters/result, checked before allocation.
                        if parameters.iter().any(|p| {
                            super::super::super::function_value::resolve::source_scalar(p).is_none()
                        }) {
                            return Ok(None);
                        }
                        let Some(result) =
                            super::super::super::function_value::resolve::source_scalar(result)
                        else {
                            return Ok(None);
                        };
                        let mut values = payer.vec(parameters.len())?;
                        for p in parameters {
                            values.push(
                                super::super::super::function_value::resolve::source_scalar(p)
                                    .unwrap(),
                            );
                        }
                        payer.bytes(size_of::<ResolvedType>() + size_of::<Box<ResolvedType>>())?;
                        ResolvedType::Function {
                            parameters: values,
                            result: Box::new(result),
                        }
                    }
                    Type::Named { name, arguments } => {
                        if arguments.is_empty() {
                            if let Some(owner) = owner {
                                if let Some(parameter) = index
                                    .type_parameters(owner)
                                    .and_then(|p| p.iter().find(|p| p.name == *name))
                                {
                                    payer.grow(&mut resolved, 1)?;
                                    resolved.push(ResolvedType::TypeParameter {
                                        owner: owner.clone(),
                                        index: parameter.index,
                                    });
                                    continue;
                                }
                            }
                        }
                        let Some(declaration) = index.type_id(name) else {
                            return Ok(None);
                        };
                        payer.grow(&mut frames, arguments.len().saturating_add(1))?;
                        frames.push(Frame::Finish(declaration.clone(), arguments.len()));
                        for argument in arguments.iter().rev() {
                            frames.push(Frame::Enter(argument));
                        }
                        continue;
                    }
                    Type::Never => return Ok(None),
                    Type::I64 => ResolvedType::I64,
                    Type::I32 => ResolvedType::I32,
                    Type::Char => ResolvedType::Char,
                    Type::U8 => ResolvedType::U8,
                    Type::Usize => ResolvedType::Usize,
                    Type::ArrayU8(n) => ResolvedType::ArrayU8(*n),
                    Type::F32 => ResolvedType::F32,
                    Type::F64 => ResolvedType::F64,
                    Type::Bool => ResolvedType::Bool,
                    Type::String => ResolvedType::String,
                    Type::Bytes => ResolvedType::Bytes,
                    Type::OnceFunction => ResolvedType::OnceFunction,
                    Type::OnceFunctionI64 => ResolvedType::OnceFunctionI64,
                    Type::OnceFunctionI64Pair => ResolvedType::OnceFunctionI64Pair,
                    Type::MutFunctionI64 => ResolvedType::MutFunctionI64,
                    Type::Str => ResolvedType::Str,
                    Type::SliceU8 => ResolvedType::SliceU8,
                    Type::StringMap => ResolvedType::StringMap,
                };
                // Acquire result storage while the root is protected by the
                // already funded construction-only recursive Drop guard.
                let value = index.nominal_drop_workspace.resolved_type(value);
                payer.grow(&mut resolved, 1)?;
                resolved.push(value.into_type());
            }
            Frame::Finish(declaration, count) => {
                let Some(split) = resolved.len().checked_sub(count) else {
                    return Ok(None);
                };
                let mut arguments = payer.vec(count)?;
                arguments.extend(resolved.drain(split..));
                // No growth is needed: draining count children frees a slot
                // except for a nullary nominal, whose growth is paid first.
                let value = index
                    .nominal_drop_workspace
                    .resolved_type(ResolvedType::Nominal {
                        declaration,
                        arguments,
                    });
                payer.grow(&mut resolved, 1)?;
                resolved.push(value.into_type());
            }
        }
    }
    Ok((resolved.len() == 1).then(|| resolved.pop().unwrap()))
}

//! Actual byte-owned construction operations for the nominal producer.
//! No ambient account, clone credit, fixed depth limit, or replay work is used.
use super::identity_payer::IdentityIndexError;
use super::nominal_rollback::Workspace;
use super::*;
use std::{fmt, mem::size_of};
pub(super) type Result<T, E> = std::result::Result<T, IdentityIndexError<E>>;
pub(super) type Reserve<'a, E> = dyn FnMut(usize) -> std::result::Result<(), E> + 'a;

pub(super) fn overflow<E>() -> IdentityIndexError<E> {
    IdentityIndexError::Semantic(Diagnostic::io_static(
        "SPX-H006",
        "nominal constructor layout overflowed",
    ))
}
pub(super) fn bytes<E>(reserve: &mut Reserve<'_, E>, n: usize) -> Result<(), E> {
    reserve(n).map_err(IdentityIndexError::Identity)
}
pub(super) fn vector_fee<T, E>(capacity: usize, reserve: &mut Reserve<'_, E>) -> Result<(), E> {
    let backing = capacity.checked_mul(size_of::<T>()).ok_or_else(overflow)?;
    bytes(
        reserve,
        backing
            .checked_add(size_of::<Vec<T>>())
            .and_then(|n| {
                n.checked_add(size_of::<std::result::Result<Vec<T>, IdentityIndexError<E>>>())
            })
            .ok_or_else(overflow)?,
    )
}
pub(super) fn vector<T, E>(capacity: usize, reserve: &mut Reserve<'_, E>) -> Result<Vec<T>, E> {
    vector_fee::<T, E>(capacity, reserve)?;
    let result = Vec::with_capacity(capacity);
    assert!(size_of::<T>() == 0 || result.capacity() == capacity);
    Ok(result)
}
pub(super) fn grow<T, E>(
    values: &mut Vec<T>,
    additional: usize,
    reserve: &mut Reserve<'_, E>,
) -> Result<(), E> {
    let needed = values.len().checked_add(additional).ok_or_else(overflow)?;
    if needed <= values.capacity() {
        return bytes(reserve, 0);
    }
    let cap = needed
        .max(values.capacity().checked_mul(2).ok_or_else(overflow)?)
        .max(4);
    let mut next = vector(cap, reserve)?;
    next.append(values);
    *values = next;
    Ok(())
}
pub(super) fn node<K, V, E>(reserve: &mut Reserve<'_, E>) -> Result<(), E> {
    bytes(
        reserve,
        crate::cleanup_plan::replay_btree_node_upper::<K, V>().ok_or_else(overflow)?,
    )
}
pub(super) fn text<E>(value: &str, reserve: &mut Reserve<'_, E>) -> Result<String, E> {
    let n = value
        .len()
        .checked_add(size_of::<String>())
        .and_then(|n| {
            n.checked_add(size_of::<std::result::Result<String, IdentityIndexError<E>>>())
        })
        .ok_or_else(overflow)?;
    bytes(reserve, n)?;
    let mut out = String::with_capacity(value.len());
    assert_eq!(out.capacity(), value.len());
    out.push_str(value);
    Ok(out)
}
struct Count(usize);
impl fmt::Write for Count {
    fn write_str(&mut self, text: &str) -> fmt::Result {
        self.0 = self.0.checked_add(text.len()).ok_or(fmt::Error)?;
        Ok(())
    }
}
pub(super) fn formatted<E>(
    args: fmt::Arguments<'_>,
    reserve: &mut Reserve<'_, E>,
) -> Result<String, E> {
    let mut count = Count(0);
    fmt::write(&mut count, args).map_err(|_| overflow())?;
    bytes(
        reserve,
        count
            .0
            .checked_add(size_of::<String>())
            .and_then(|n| {
                n.checked_add(size_of::<std::result::Result<String, IdentityIndexError<E>>>())
            })
            .ok_or_else(overflow)?,
    )?;
    let mut out = String::with_capacity(count.0);
    assert_eq!(out.capacity(), count.0);
    fmt::write(&mut out, args).expect("exact paid String formatter");
    assert_eq!(out.len(), count.0);
    Ok(out)
}
pub(super) fn diagnostic<E>(
    code: &'static str,
    args: fmt::Arguments<'_>,
    span: crate::ast::Span,
    path: &str,
    reserve: &mut Reserve<'_, E>,
) -> Result<Diagnostic, E> {
    bytes(
        reserve,
        size_of::<Diagnostic>()
            + size_of::<std::result::Result<Diagnostic, IdentityIndexError<E>>>(),
    )?;
    let message = formatted(args, reserve)?;
    let path = text(path, reserve)?;
    Ok(Diagnostic {
        code,
        severity: crate::diagnostic::Severity::Error,
        message: std::borrow::Cow::Owned(message),
        path: Some(path),
        span: Some(span),
        help: None,
    })
}
impl Workspace {
    pub(super) fn ensure_paid_frontier<E>(
        &self,
        capacity: usize,
        reserve: &mut Reserve<'_, E>,
    ) -> Result<(), E> {
        bytes(reserve, 0)?;
        let scratch = self.scratch.as_ref().expect("paid construction workspace");
        let mut held = scratch.lock().expect("primed construction disposal lock");
        assert!(
            held.is_empty(),
            "only grow the disposal frontier outside Drop"
        );
        if capacity > held.capacity() {
            let replacement = vector::<ResolvedType, E>(capacity, reserve)?;
            *held = replacement;
        }
        Ok(())
    }
}
/// Census follows the exact final-owner disposal order. Each cloned Vec/Box
/// allocation is counted at its source node; the traversal itself is paid.
/// The source is borrowed, so a refused census has no recursive owned rollback.
pub(super) fn clone_type<E>(
    root: &ResolvedType,
    workspace: &Workspace,
    reserve: &mut Reserve<'_, E>,
) -> Result<ResolvedType, E> {
    if !matches!(root, ResolvedType::Nominal { arguments, .. } if !arguments.is_empty())
        && !matches!(root, ResolvedType::Function { .. })
    {
        bytes(
            reserve,
            size_of::<ResolvedType>()
                + size_of::<std::result::Result<ResolvedType, IdentityIndexError<E>>>(),
        )?;
        return Ok(root.clone());
    }
    let mut pending = vector::<&ResolvedType, E>(1, reserve)?;
    pending.push(root);
    let mut payload = 0usize;
    let mut frontier = 0;
    while let Some(ty) = pending.pop() {
        let (children, boxed) = match ty {
            ResolvedType::Nominal { arguments, .. } => (arguments.as_slice(), None),
            ResolvedType::Function { parameters, result } => {
                (parameters.as_slice(), Some(result.as_ref()))
            }
            _ => (&[][..], None),
        };
        payload = payload
            .checked_add(
                children
                    .len()
                    .checked_mul(size_of::<ResolvedType>())
                    .ok_or_else(overflow)?,
            )
            .ok_or_else(overflow)?;
        if boxed.is_some() {
            payload = payload
                .checked_add(size_of::<ResolvedType>())
                .ok_or_else(overflow)?;
        }
        grow(
            &mut pending,
            children.len() + usize::from(boxed.is_some()),
            reserve,
        )?;
        pending.extend(children);
        if let Some(result) = boxed {
            pending.push(result);
        }
        frontier = frontier.max(pending.len());
    }
    workspace.ensure_paid_frontier(frontier, reserve)?;
    bytes(
        reserve,
        payload
            .checked_add(size_of::<ResolvedType>())
            .and_then(|n| {
                n.checked_add(size_of::<
                    std::result::Result<ResolvedType, IdentityIndexError<E>>,
                >())
            })
            .ok_or_else(overflow)?,
    )?;
    Ok(root.clone())
}
pub(super) fn field<E>(
    field: &ResolvedFieldDeclaration,
    workspace: &Workspace,
    reserve: &mut Reserve<'_, E>,
) -> Result<ResolvedFieldDeclaration, E> {
    bytes(
        reserve,
        size_of::<ResolvedFieldDeclaration>()
            + size_of::<std::result::Result<ResolvedFieldDeclaration, IdentityIndexError<E>>>(),
    )?;
    let name = text(&field.name, reserve)?;
    let ty = clone_type(&field.ty, workspace, reserve)?;
    // No subsequent reservation occurs while the complete root is unguarded.
    Ok(ResolvedFieldDeclaration {
        id: field.id.clone(),
        name,
        ty,
        index: field.index,
        span: field.span,
    })
}

fn template_error<E>(
    args: fmt::Arguments<'_>,
    reserve: &mut Reserve<'_, E>,
) -> Result<Diagnostic, E> {
    bytes(
        reserve,
        size_of::<Diagnostic>()
            + size_of::<std::result::Result<Diagnostic, IdentityIndexError<E>>>(),
    )?;
    Ok(Diagnostic::io("SPX-H006", formatted(args, reserve)?))
}
fn substituted<'a, E>(
    ty: &'a ResolvedType,
    active: bool,
    owner: &DeclarationId,
    arguments: &'a [ResolvedType],
    reserve: &mut Reserve<'_, E>,
) -> Result<(&'a ResolvedType, bool), E> {
    if active {
        if let ResolvedType::TypeParameter {
            owner: actual,
            index,
        } = ty
        {
            if actual != owner {
                return Err(template_error(
                    format_args!(
                        "type template for `{owner}` contains foreign parameter owner `{actual}`"
                    ),
                    reserve,
                )?
                .into());
            }
            let Ok(at) = usize::try_from(*index) else {
                return Err(template_error(
                    format_args!("type parameter index {index} does not fit usize"),
                    reserve,
                )?
                .into());
            };
            let Some(argument) = arguments.get(at) else {
                return Err(template_error(
                    format_args!(
                        "type template for `{owner}` references missing parameter {index}"
                    ),
                    reserve,
                )?
                .into());
            };
            return Ok((argument, false));
        }
    }
    Ok((ty, active))
}
/// The old substitution's complete value/error semantics with explicit storage.
/// The borrowed expanded-tree census pays its own cursor and prepares exactly
/// the disposal frontier needed by the resulting tree, with no depth quota.
pub(super) fn substitute_type<E>(
    template: &ResolvedType,
    owner: &DeclarationId,
    arguments: &[ResolvedType],
    workspace: &Workspace,
    reserve: &mut Reserve<'_, E>,
) -> Result<ResolvedType, E> {
    let root = substituted(template, true, owner, arguments, reserve)?;
    let mut census = vector(1, reserve)?;
    census.push(root);
    // Diagnose templates in the old source order before walking the expanded
    // disposal order (which deliberately visits siblings in reverse).
    while let Some((ty, active)) = census.pop() {
        let (ty, active) = substituted(ty, active, owner, arguments, reserve)?;
        match ty {
            ResolvedType::Nominal {
                arguments: nested, ..
            } => {
                grow(&mut census, nested.len(), reserve)?;
                census.extend(nested.iter().rev().map(|ty| (ty, active)));
            }
            ResolvedType::Function { parameters, result } => {
                grow(
                    &mut census,
                    parameters.len().checked_add(1).ok_or_else(overflow)?,
                    reserve,
                )?;
                census.push((result.as_ref(), active));
                census.extend(parameters.iter().rev().map(|ty| (ty, active)));
            }
            _ => {}
        }
    }
    census.push(root);
    let mut frontier = 0;
    while let Some((ty, active)) = census.pop() {
        let (children, result) = match ty {
            ResolvedType::Nominal { arguments, .. } => (arguments.as_slice(), None),
            ResolvedType::Function { parameters, result } => {
                (parameters.as_slice(), Some(result.as_ref()))
            }
            _ => (&[][..], None),
        };
        grow(
            &mut census,
            children
                .len()
                .checked_add(usize::from(result.is_some()))
                .ok_or_else(overflow)?,
            reserve,
        )?;
        for child in children {
            census.push(substituted(child, active, owner, arguments, reserve)?);
        }
        if let Some(result) = result {
            census.push(substituted(result, active, owner, arguments, reserve)?);
        }
        frontier = frontier.max(census.len());
    }
    workspace.ensure_paid_frontier(frontier, reserve)?;
    enum Frame<'a> {
        Enter(&'a ResolvedType, bool),
        Nominal(&'a DeclarationId, usize),
        Callable(usize),
    }
    let mut frames = vector(1, reserve)?;
    frames.push(Frame::Enter(root.0, root.1));
    bytes(
        reserve,
        size_of::<super::nominal_rollback::PendingTypes>()
            + size_of::<Vec<ResolvedType>>()
            + size_of::<std::result::Result<ResolvedType, IdentityIndexError<E>>>(),
    )?;
    let mut values = workspace.types();
    while let Some(frame) = frames.pop() {
        match frame {
            Frame::Enter(ty, active) => {
                let (ty, active) = substituted(ty, active, owner, arguments, reserve)?;
                match ty {
                    ResolvedType::Nominal {
                        declaration,
                        arguments,
                    } => {
                        grow(
                            &mut frames,
                            arguments.len().checked_add(1).ok_or_else(overflow)?,
                            reserve,
                        )?;
                        frames.push(Frame::Nominal(declaration, arguments.len()));
                        frames.extend(arguments.iter().rev().map(|ty| Frame::Enter(ty, active)));
                    }
                    ResolvedType::Function { parameters, result } => {
                        grow(
                            &mut frames,
                            parameters.len().checked_add(2).ok_or_else(overflow)?,
                            reserve,
                        )?;
                        frames.push(Frame::Callable(parameters.len()));
                        frames.push(Frame::Enter(result, active));
                        frames.extend(parameters.iter().rev().map(|ty| Frame::Enter(ty, active)));
                    }
                    leaf => {
                        grow(&mut values, 1, reserve)?;
                        bytes(reserve, size_of::<ResolvedType>())?;
                        values.push(leaf.clone());
                    }
                }
            }
            Frame::Nominal(declaration, count) => {
                let split = values.len().checked_sub(count).ok_or_else(overflow)?;
                if count == 0 {
                    grow(&mut values, 1, reserve)?;
                }
                let mut nested = vector(count, reserve)?;
                // No callback follows removal of recursive children from the
                // shared guarded pool until their new root is guarded again.
                nested.extend(values.drain(split..));
                values.push(ResolvedType::Nominal {
                    declaration: declaration.clone(),
                    arguments: nested,
                });
            }
            Frame::Callable(count) => {
                let split = values
                    .len()
                    .checked_sub(count.checked_add(1).ok_or_else(overflow)?)
                    .ok_or_else(overflow)?;
                let mut parameters = vector(count, reserve)?;
                bytes(
                    reserve,
                    size_of::<ResolvedType>() + size_of::<Box<ResolvedType>>(),
                )?;
                let result = Box::new(values.pop().expect("complete callable result"));
                parameters.extend(values.drain(split..));
                values.push(ResolvedType::Function { parameters, result });
            }
        }
    }
    assert_eq!(values.len(), 1);
    Ok(values.pop().expect("one complete substituted type"))
}

//! Independently paid class-inheritance producer; the complete old helper stays.
use super::identity_payer::IdentityIndexError;
use super::nominal_paid_values as paid;
use super::nominal_rollback::PendingVec;
use super::*;
use std::mem::size_of;
impl DeclarationIndex {
    pub(super) fn materialize_class_inheritance_paid<E>(
        &mut self,
        program: &dyn ProgramSource,
        reserve: &mut paid::Reserve<'_, E>,
    ) -> paid::Result<(), E> {
        paid::bytes(reserve, 0)?;
        for declaration in program.types() {
            let Some(extends) = &declaration.extends else {
                continue;
            };
            let child = self.inserted_identity(&declaration.stable_id);
            let Type::Named {
                name: parent_name,
                arguments: parent_arguments,
            } = extends
            else {
                return Err(paid::diagnostic(
                    "SPX-T227",
                    format_args!(
                        "class `{}` must extend a named class type",
                        declaration.name
                    ),
                    declaration.name_span,
                    program.path(),
                    reserve,
                )?
                .into());
            };
            if !parent_arguments.is_empty() {
                return Err(paid::diagnostic("SPX-T227", format_args!("class `{}` extends generic type `{parent_name}`; inheritance over generic classes is closed in this slice", declaration.name), declaration.name_span, program.path(), reserve)?.into());
            }
            let Some(parent) = self.types_by_name.get(parent_name) else {
                return Err(paid::diagnostic(
                    "SPX-T227",
                    format_args!(
                        "class `{}` extends unknown type `{parent_name}`",
                        declaration.name
                    ),
                    declaration.name_span,
                    program.path(),
                    reserve,
                )?
                .into());
            };
            if self
                .declaration(parent)
                .is_none_or(|item| item.kind != DeclarationKind::Class)
            {
                return Err(paid::diagnostic(
                    "SPX-T227",
                    format_args!(
                        "class `{}` extends non-class type `{parent_name}`",
                        declaration.name
                    ),
                    declaration.name_span,
                    program.path(),
                    reserve,
                )?
                .into());
            }
            if !self.class_parents.contains_key(&child) {
                paid::node::<DeclarationId, DeclarationId, E>(reserve)?;
            }
            self.class_parents.insert(child, parent.clone());
        }
        for declaration in program.types() {
            if !matches!(declaration.kind, TypeDeclarationKind::Class { .. }) {
                continue;
            }
            let child = self.inserted_identity(&declaration.stable_id);
            paid::bytes(reserve, size_of::<BTreeSet<DeclarationId>>())?;
            let mut visited = BTreeSet::new();
            let mut cursor = child.clone();
            while let Some(parent) = self.class_parents.get(&cursor) {
                if parent == &child || visited.contains(parent) {
                    return Err(paid::diagnostic(
                        "SPX-T228",
                        format_args!(
                            "class `{}` participates in an inheritance cycle",
                            declaration.name
                        ),
                        declaration.span,
                        program.path(),
                        reserve,
                    )?
                    .into());
                }
                paid::node::<DeclarationId, (), E>(reserve)?;
                visited.insert(parent.clone());
                cursor = parent.clone();
            }
        }
        paid::bytes(
            reserve,
            size_of::<BTreeMap<DeclarationId, PendingVec<ResolvedFieldDeclaration>>>(),
        )?;
        let mut declared_fields = BTreeMap::new();
        for declaration in program.types() {
            if !matches!(declaration.kind, TypeDeclarationKind::Class { .. }) {
                continue;
            }
            let id = self.inserted_identity(&declaration.stable_id);
            if let Some(fields) = self.record_fields(&id) {
                paid::node::<DeclarationId, PendingVec<ResolvedFieldDeclaration>, E>(reserve)?;
                paid::vector_fee::<ResolvedFieldDeclaration, E>(fields.len(), reserve)?;
                paid::bytes(
                    reserve,
                    size_of::<PendingVec<ResolvedFieldDeclaration>>()
                        + size_of::<
                            std::result::Result<
                                PendingVec<ResolvedFieldDeclaration>,
                                IdentityIndexError<E>,
                            >,
                        >(),
                )?;
                let mut snapshot = self.nominal_drop_workspace.fields(fields.len());
                for field in fields {
                    snapshot.push(paid::field(field, &self.nominal_drop_workspace, reserve)?);
                }
                declared_fields.insert(id, snapshot);
            }
        }
        for declaration in program.types() {
            let TypeDeclarationKind::Class { .. } = &declaration.kind else {
                continue;
            };
            let child = self.inserted_identity(&declaration.stable_id);
            let mut count = 1usize;
            let mut cursor = &child;
            while let Some(parent) = self.class_parents.get(cursor) {
                count = count.checked_add(1).ok_or_else(paid::overflow)?;
                cursor = parent;
            }
            let mut chain = paid::vector(count, reserve)?;
            let mut cursor = &child;
            while let Some(parent) = self.class_parents.get(cursor) {
                chain.push(parent.clone());
                cursor = parent;
            }
            chain.reverse();
            chain.push(child.clone());
            let mut capacity = 0usize;
            for member in &chain {
                if let Some(fields) = declared_fields.get(member) {
                    capacity = capacity
                        .checked_add(fields.len())
                        .ok_or_else(paid::overflow)?;
                }
            }
            paid::vector_fee::<ResolvedFieldDeclaration, E>(capacity, reserve)?;
            paid::bytes(
                reserve,
                size_of::<PendingVec<ResolvedFieldDeclaration>>()
                    + size_of::<BTreeSet<String>>()
                    + size_of::<BTreeSet<DeclarationId>>(),
            )?;
            let mut effective = self.nominal_drop_workspace.fields(capacity);
            let mut seen_names = BTreeSet::new();
            let mut seen_ids = BTreeSet::new();
            for member in &chain {
                let is_child = member == &child;
                let Some(fields) = declared_fields.get(member) else {
                    return Err(paid::diagnostic(
                        "SPX-H006",
                        format_args!("class `{member}` has no resolved fields"),
                        declaration.span,
                        program.path(),
                        reserve,
                    )?
                    .into());
                };
                for original in fields.iter() {
                    if seen_names.contains(&original.name) || seen_ids.contains(&original.id) {
                        return Err(paid::diagnostic(
                            "SPX-T229",
                            format_args!(
                                "class `{}` redeclares member `{}` from an ancestor",
                                declaration.name, original.name
                            ),
                            original.span,
                            program.path(),
                            reserve,
                        )?
                        .into());
                    }
                    let name = paid::text(&original.name, reserve)?;
                    paid::node::<String, (), E>(reserve)?;
                    seen_names.insert(name);
                    paid::node::<DeclarationId, (), E>(reserve)?;
                    seen_ids.insert(original.id.clone());
                    let Ok(index) = u32::try_from(effective.len()) else {
                        return Err(paid::diagnostic(
                            "SPX-H006",
                            format_args!("class `{}` has too many fields", declaration.name),
                            declaration.span,
                            program.path(),
                            reserve,
                        )?
                        .into());
                    };
                    if !is_child {
                        let key = (child.clone(), paid::text(&original.name, reserve)?);
                        if !self.fields_by_owner_name.contains_key(&key) {
                            paid::node::<(DeclarationId, String), DeclarationId, E>(reserve)?;
                        }
                        self.fields_by_owner_name.insert(key, original.id.clone());
                    }
                    let mut field = paid::field(original, &self.nominal_drop_workspace, reserve)?;
                    field.index = index;
                    effective.push(field);
                }
            }
            paid::bytes(
                reserve,
                size_of::<Option<NominalPayload<ResolvedFieldDeclaration>>>(),
            )?;
            if let Some(previous) = self.record_fields.insert(child, effective.into_vec()) {
                previous.drain_recursive_types(|ty| {
                    drop(self.nominal_drop_workspace.resolved_type(ty))
                });
            }
        }
        Ok(())
    }
}

//! Complete paid TypeFacts construction on the nominal constructor's raw owner.
//! Registered only as a child of flags::paid, so the existing key/text/builtin
//! producer factors stay private and the complete old constructor stays intact.
use super::super::super::{
    admitted_owned_byte_prelude_instance, owned_builtin, DeclarationId, DeclarationIndex,
    DeclarationKind, ResolvedType, TypeFacts,
};
use super::storage::{Payer, Storage};
use super::{admission, builtin, key};
use crate::diagnostic::Diagnostic;
use crate::hir::declaration_index::{
    identity_payer::IdentityIndexError,
    nominal_paid_values as paid,
    nominal_rollback::{PendingTypes, Workspace},
};
use std::{
    collections::{BTreeMap, BTreeSet},
    mem::size_of,
};

struct TypeGuard<'a> {
    value: Option<ResolvedType>,
    workspace: &'a Workspace,
}
impl<'a> TypeGuard<'a> {
    fn new(value: ResolvedType, workspace: &'a Workspace) -> Self {
        Self {
            value: Some(value),
            workspace,
        }
    }
    fn as_type(&self) -> &ResolvedType {
        self.value.as_ref().expect("held classifier root")
    }
}
impl Drop for TypeGuard<'_> {
    fn drop(&mut self) {
        if let Some(ty) = self.value.take() {
            drop(self.workspace.resolved_type(ty));
        }
    }
}
fn sentinel() -> Diagnostic {
    Diagnostic::io_static("SPX-H006", "held nominal constructor refusal")
}
struct ConstructorPayer<'r, 'callback, 'w, E> {
    reserve: &'r mut paid::Reserve<'callback, E>,
    workspace: &'w Workspace,
    first: Option<E>,
}
impl<E> ConstructorPayer<'_, '_, '_, E> {
    fn receive<T>(&mut self, result: paid::Result<T, E>) -> std::result::Result<T, Diagnostic> {
        match result {
            Ok(value) => Ok(value),
            Err(IdentityIndexError::Identity(error)) => {
                if self.first.is_none() {
                    self.first = Some(error);
                }
                Err(sentinel())
            }
            Err(IdentityIndexError::Semantic(error)) => Err(error),
        }
    }
    fn substitute(
        &mut self,
        ty: &ResolvedType,
        owner: &DeclarationId,
        arguments: &[ResolvedType],
    ) -> std::result::Result<ResolvedType, Diagnostic> {
        if self.first.is_some() {
            return Err(sentinel());
        }
        let result = paid::substitute_type(ty, owner, arguments, self.workspace, self.reserve);
        self.receive(result)
    }
}
impl<E> Payer for ConstructorPayer<'_, '_, '_, E> {
    fn bytes(&mut self, n: usize) -> std::result::Result<(), Diagnostic> {
        if self.first.is_some() {
            return Err(sentinel());
        }
        let result = paid::bytes(self.reserve, n);
        self.receive(result)
    }
    fn grow<T>(&mut self, values: &mut Vec<T>, add: usize) -> std::result::Result<(), Diagnostic> {
        if self.first.is_some() {
            return Err(sentinel());
        }
        let result = paid::grow(values, add, self.reserve);
        self.receive(result)
    }
    fn node<K, V>(&mut self) -> std::result::Result<(), Diagnostic> {
        if self.first.is_some() {
            return Err(sentinel());
        }
        let result = paid::node::<K, V, E>(self.reserve);
        self.receive(result)
    }
    fn clone_type(&mut self, ty: &ResolvedType) -> std::result::Result<ResolvedType, Diagnostic> {
        if self.first.is_some() {
            return Err(sentinel());
        }
        let result = paid::clone_type(ty, self.workspace, self.reserve);
        self.receive(result)
    }
    fn boxed_type(
        &mut self,
        ty: ResolvedType,
    ) -> std::result::Result<Box<ResolvedType>, Diagnostic> {
        let guarded = self.workspace.resolved_type(ty);
        self.bytes(size_of::<ResolvedType>() + size_of::<Box<ResolvedType>>())?;
        Ok(Box::new(guarded.into_type()))
    }
    fn construction_refusal(&mut self, message: &'static str) -> Diagnostic {
        if self.first.is_some() {
            sentinel()
        } else {
            Diagnostic::io_static("SPX-H006", message)
        }
    }
    // The existing production Payer has only physical byte operations. Its
    // unchanged cfg(test) default grants no oracle work lease or new account.
}
fn children<'a, E>(
    types: impl Iterator<Item = &'a ResolvedType>,
    owner: &DeclarationId,
    arguments: &[ResolvedType],
    storage: &mut Storage<ConstructorPayer<'_, '_, '_, E>>,
    workspace: &Workspace,
) -> Option<PendingTypes> {
    storage.bytes(size_of::<PendingTypes>() + size_of::<Vec<ResolvedType>>())?;
    let mut children = workspace.types();
    for ty in types {
        storage.grow(&mut children, 1)?;
        let result = storage.payer.substitute(ty, owner, arguments);
        let child = storage.receive(result)?;
        children.push(child);
    }
    Some(children)
}
impl DeclarationIndex {
    pub(in crate::hir::declaration_index) fn populate_type_facts_paid<E>(
        &mut self,
        reserve: &mut paid::Reserve<'_, E>,
    ) -> paid::Result<bool, E> {
        paid::bytes(
            reserve,
            size_of::<Storage<ConstructorPayer<'_, '_, '_, E>>>()
                + size_of::<ConstructorPayer<'_, '_, '_, E>>()
                + size_of::<BTreeMap<String, TypeFacts>>()
                + size_of::<std::result::Result<bool, IdentityIndexError<E>>>(),
        )?;
        let workspace = &self.nominal_drop_workspace;
        let mut storage = Storage {
            payer: ConstructorPayer {
                reserve,
                workspace,
                first: None,
            },
            first: None,
        };
        let mut memo = BTreeMap::new();
        let valid = (|| {
            for ty in [ResolvedType::I64, ResolvedType::Bool] {
                let facts = self.compute_nominal_paid_type_facts(
                    &ty,
                    &mut BTreeSet::new(),
                    &mut memo,
                    &mut storage,
                    workspace,
                )?;
                let identity = key::identity(&ty, &mut storage)?;
                if !memo.contains_key(&identity) {
                    storage.node::<String, TypeFacts>()?;
                }
                memo.insert(identity, facts);
            }
            // Borrow the exact old name-sorted declaration order; no snapshot
            // clone or new trusted cache fact is introduced.
            for declaration in self.types_by_name.values() {
                if self
                    .type_parameters
                    .get(declaration)
                    .is_some_and(|parameters| !parameters.is_empty())
                {
                    continue;
                }
                storage.bytes(size_of::<ResolvedType>())?;
                let ty = ResolvedType::Nominal {
                    declaration: declaration.clone(),
                    arguments: Vec::new(),
                };
                self.compute_nominal_paid_type_facts(
                    &ty,
                    &mut BTreeSet::new(),
                    &mut memo,
                    &mut storage,
                    workspace,
                )?;
            }
            Some(())
        })()
        .is_some();
        let raw = storage.payer.first.take();
        let diagnostic = storage.first.take();
        drop(storage);
        if let Some(error) = raw {
            return Err(IdentityIndexError::Identity(error));
        }
        if let Some(error) = diagnostic {
            return Err(IdentityIndexError::Semantic(error));
        }
        if valid {
            self.type_facts_by_id = memo;
        }
        Ok(valid)
    }
}

impl DeclarationIndex {
    fn compute_nominal_paid_type_facts<E>(
        &self,
        ty: &ResolvedType,
        visiting: &mut BTreeSet<String>,
        memo: &mut BTreeMap<String, TypeFacts>,
        storage: &mut Storage<ConstructorPayer<'_, '_, '_, E>>,
        workspace: &Workspace,
    ) -> Option<TypeFacts> {
        enum Frame<'a> {
            Enter(TypeGuard<'a>),
            Finish {
                identity: String,
                declaration: DeclarationId,
                kind: DeclarationKind,
                child_count: usize,
            },
        }

        storage.bytes(
            size_of::<Vec<Frame<'_>>>()
                + size_of::<Vec<TypeFacts>>()
                + size_of::<BTreeSet<String>>()
                + size_of::<Option<TypeFacts>>()
                + size_of::<TypeGuard<'_>>(),
        )?;
        let mut frames = Vec::new();
        let root = TypeGuard::new(storage.clone_type(ty)?, workspace);
        storage.push(&mut frames, Frame::Enter(root))?;
        let mut results = Vec::<TypeFacts>::new();
        while let Some(frame) = frames.pop() {
            #[cfg(test)]
            storage.oracle_work(1, "classifier compute frame")?;
            match frame {
                Frame::Enter(held) => {
                    let ty = held.as_type();
                    let identity = key::identity(ty, storage)?;

                    if let Some(facts) = memo.get(&identity) {
                        let facts = storage.facts_clone(facts)?;
                        storage.push(&mut results, facts)?;
                        continue;
                    }
                    if crate::map_ops::is_typed_collection(ty) {
                        storage.grow(&mut results, 1)?;
                        results.push(TypeFacts {
                            copy: false,
                            contains_resource: false,
                            sized: true,
                            needs_drop: true,
                            layout_key: {
                                let key = key::identity(ty, storage)?;
                                storage.text(format_args!("owned:collection:{}", key))?
                            },
                        });
                        continue;
                    }
                    let scalar = match ty {
                        ResolvedType::Function { .. } => {
                            if !crate::hir::function_value::is_signature(ty) {
                                return None;
                            }
                            storage.grow(&mut results, 1)?;
                            results.push(TypeFacts {
                                copy: true,
                                contains_resource: false,
                                sized: true,
                                needs_drop: false,
                                layout_key: storage.literal(&identity)?,
                            });
                            continue;
                        }
                        ResolvedType::Never => None,
                        ResolvedType::Unit => {
                            Some((true, false, false, "native-rust-import-result:unit"))
                        }
                        ResolvedType::I64 => Some((true, false, false, "scalar:i64")),
                        ResolvedType::I32 => Some((true, false, false, "scalar:i32")),
                        ResolvedType::Char => Some((true, false, false, "scalar:char")),
                        ResolvedType::U8 => Some((true, false, false, "scalar:u8")),
                        ResolvedType::Usize => Some((true, false, false, "scalar:usize")),
                        ResolvedType::ArrayU8(_) => None,
                        ResolvedType::F32 => Some((true, false, false, "scalar:f32")),
                        ResolvedType::F64 => Some((true, false, false, "scalar:f64")),
                        ResolvedType::Bool => Some((true, false, false, "scalar:bool")),
                        ResolvedType::String => Some((false, false, true, "owned:string")),
                        ResolvedType::Bytes => Some((false, false, true, "owned:bytes")),
                        ResolvedType::OnceFunctionI64 => {
                            Some((false, false, true, "owned:fn-once:bytes+i64:i64:v2"))
                        }
                        ResolvedType::MutFunctionI64 => {
                            Some((false, false, false, "owned:fn-mut:i64+i64:i64:v1"))
                        }
                        ResolvedType::OnceFunctionI64Pair => {
                            Some((false, false, true, "owned:fn-once:bytes+i64+i64:i64:v3"))
                        }
                        ResolvedType::OnceFunction => {
                            Some((false, false, true, "owned:fn-once:bytes:i64:v1"))
                        }
                        ResolvedType::Str => Some((false, false, false, "borrowed:str")),
                        ResolvedType::SliceU8 => Some((false, false, false, "borrowed:slice-u8")),
                        ResolvedType::StringMap => {
                            Some((false, false, true, "owned:map:string:i64"))
                        }
                        ResolvedType::TypeParameter { .. } | ResolvedType::Nominal { .. } => None,
                    };
                    if let ResolvedType::ArrayU8(length) = ty {
                        storage.grow(&mut results, 1)?;
                        results.push(TypeFacts {
                            copy: true,
                            contains_resource: false,
                            sized: true,
                            needs_drop: false,
                            layout_key: storage.text(format_args!("array:u8:{length}"))?,
                        });
                        continue;
                    }
                    if let Some((copy, contains_resource, needs_drop, key)) = scalar {
                        storage.grow(&mut results, 1)?;
                        results.push(TypeFacts {
                            copy,
                            contains_resource,
                            sized: true,
                            needs_drop,
                            layout_key: storage.literal(key)?,
                        });
                        continue;
                    }
                    let native_owned_container = admission::native_owned(self, ty)
                        || owned_builtin::resource_result_shape(self, ty);
                    let authored_owned_byte_variant = admission::authored_byte_variant(self, ty);
                    let ResolvedType::Nominal {
                        declaration,
                        arguments,
                    } = ty
                    else {
                        return None;
                    };
                    let item = self.declaration(declaration)?;
                    if let Some(facts) = builtin::facts(self, declaration, arguments, storage) {
                        if !memo.contains_key(&identity) {
                            storage.node::<String, TypeFacts>()?;
                        }
                        let retained = storage.facts_clone(&facts)?;
                        memo.insert(identity, retained);
                        storage.push(&mut results, facts)?;
                        continue;
                    }
                    if storage.first.is_some() {
                        return None;
                    }
                    if item.kind == DeclarationKind::Resource && arguments.is_empty() {
                        let facts = TypeFacts {
                            copy: false,
                            contains_resource: true,
                            sized: true,
                            needs_drop: true,
                            layout_key: storage.text(format_args!("resource:{identity}"))?,
                        };
                        if !memo.contains_key(&identity) {
                            storage.node::<String, TypeFacts>()?;
                        }
                        let retained = storage.facts_clone(&facts)?;
                        memo.insert(identity, retained);
                        storage.push(&mut results, facts)?;
                        continue;
                    }
                    if !matches!(
                        item.kind,
                        DeclarationKind::Record | DeclarationKind::Class | DeclarationKind::Variant
                    ) {
                        return None;
                    }
                    let parameters = self.type_parameters.get(declaration)?;
                    let compiler_byte_option = declaration.as_str() == crate::prelude::OPTION_ID
                        && arguments.as_slice() == [ResolvedType::U8];
                    let owned_byte_variant =
                        admitted_owned_byte_prelude_instance(declaration, arguments)
                            || authored_owned_byte_variant;
                    if arguments.len() != parameters.len()
                        || (!compiler_byte_option
                            && !owned_byte_variant
                            && !native_owned_container
                            && item.kind != DeclarationKind::Record
                            && arguments.iter().any(|argument| {
                                !matches!(argument, ResolvedType::I64 | ResolvedType::Bool)
                            }))
                    {
                        return None;
                    }
                    let visiting_key = storage.literal(&identity)?;
                    if !visiting.contains(&identity) {
                        storage.node::<String, ()>()?;
                    }
                    if !visiting.insert(visiting_key) {
                        return None;
                    }
                    let children = match item.kind {
                        DeclarationKind::Record | DeclarationKind::Class => children(
                            self.record_fields
                                .get(declaration)?
                                .iter()
                                .map(|field| &field.ty),
                            declaration,
                            arguments,
                            storage,
                            workspace,
                        )?,
                        DeclarationKind::Variant => children(
                            self.variant_cases
                                .get(declaration)?
                                .iter()
                                .flat_map(|case| &case.fields)
                                .map(|field| &field.ty),
                            declaration,
                            arguments,
                            storage,
                            workspace,
                        )?,
                        _ => unreachable!(),
                    };

                    storage.bytes(
                        children
                            .len()
                            .checked_mul(std::mem::size_of::<TypeGuard<'_>>())?,
                    )?;
                    storage.grow(&mut frames, children.len().checked_add(1)?)?;
                    frames.push(Frame::Finish {
                        identity,
                        declaration: declaration.clone(),
                        kind: item.kind,
                        child_count: children.len(),
                    });
                    frames.extend(
                        children
                            .into_vec()
                            .into_iter()
                            .rev()
                            .map(|ty| Frame::Enter(TypeGuard::new(ty, workspace))),
                    );
                }
                Frame::Finish {
                    identity,
                    declaration,
                    kind,
                    child_count,
                } => {
                    let split = results.len().checked_sub(child_count)?;
                    let child_facts = &results[split..];

                    visiting.remove(&identity);
                    let mut encoded = storage.encoded()?;
                    match kind {
                        DeclarationKind::Record | DeclarationKind::Class => {
                            let fields = self.record_fields.get(&declaration)?;
                            let mut copy = true;
                            let mut contains_resource = false;
                            let mut sized = true;
                            let mut needs_drop = false;
                            for (field, facts) in fields.iter().zip(child_facts) {
                                #[cfg(test)]
                                storage.oracle_work(1, "classifier declared field receive")?;
                                copy &= facts.copy;
                                contains_resource |= facts.contains_resource;
                                sized &= facts.sized;
                                needs_drop |= facts.needs_drop;
                                storage.append(
                                    &mut encoded,
                                    format_args!(
                                        "{}:{}:{}:{}",
                                        field.id.as_str().len(),
                                        field.id,
                                        facts.layout_key.len(),
                                        facts.layout_key
                                    ),
                                )?;
                            }

                            let prefix = if kind == DeclarationKind::Class {
                                "class"
                            } else {
                                "record"
                            };
                            let facts = TypeFacts {
                                copy,
                                contains_resource,
                                sized,
                                needs_drop,
                                layout_key: storage.text(format_args!(
                                    "{prefix}:{}:{}:{}:{}",
                                    declaration.as_str().len(),
                                    declaration,
                                    fields.len(),
                                    encoded.into_string()
                                ))?,
                            };

                            if !memo.contains_key(&identity) {
                                storage.node::<String, TypeFacts>()?;
                            }
                            let retained = storage.facts_clone(&facts)?;
                            memo.insert(identity, retained);
                            results.truncate(split);
                            storage.push(&mut results, facts)?;
                        }
                        DeclarationKind::Variant => {
                            let cases = self.variant_cases.get(&declaration)?;
                            let mut facts_iter = child_facts.iter();
                            let mut copy = true;
                            let mut contains_resource = false;
                            let mut sized = true;
                            let mut needs_drop = false;
                            for case in cases {
                                #[cfg(test)]
                                storage.oracle_work(1, "classifier declared field receive")?;
                                storage.append(
                                    &mut encoded,
                                    format_args!(
                                        "{}:{}:{}:",
                                        case.id.as_str().len(),
                                        case.id,
                                        case.fields.len()
                                    ),
                                )?;
                                for field in &case.fields {
                                    #[cfg(test)]
                                    storage.oracle_work(1, "classifier declared field receive")?;
                                    let facts = facts_iter.next()?;
                                    copy &= facts.copy;
                                    contains_resource |= facts.contains_resource;
                                    sized &= facts.sized;
                                    needs_drop |= facts.needs_drop;
                                    storage.append(
                                        &mut encoded,
                                        format_args!(
                                            "{}:{}:{}:{}",
                                            field.id.as_str().len(),
                                            field.id,
                                            facts.layout_key.len(),
                                            facts.layout_key
                                        ),
                                    )?;
                                }
                            }

                            let facts = TypeFacts {
                                copy,
                                contains_resource,
                                sized,
                                needs_drop,
                                layout_key: storage.text(format_args!(
                                    "variant:{}:{}:{}:{}",
                                    declaration.as_str().len(),
                                    declaration,
                                    cases.len(),
                                    encoded.into_string()
                                ))?,
                            };

                            if !memo.contains_key(&identity) {
                                storage.node::<String, TypeFacts>()?;
                            }
                            let retained = storage.facts_clone(&facts)?;
                            memo.insert(identity, retained);
                            results.truncate(split);
                            storage.push(&mut results, facts)?;
                        }
                        _ => unreachable!(),
                    }
                }
            }
        }
        (results.len() == 1).then(|| results.pop().expect("type fact count checked above"))
    }
}

