//! Additive full-constructor control for the semantic T217 publication boundary.
use super::*;
use crate::bounded_output::{reserve_active_required, with_limit_usage_refusal};
use crate::test_allocation_observer::{current_metrics, measure};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Stop(usize);

#[test]
fn nominal_invalid_recursive_layout_keeps_old_report_and_funds_every_refusal_and_drop() {
    const PATH: &str = "nominal-invalid-layout.spx";
    const SOURCE: &str = r#"module nominal.invalid_layout;
@id("recursive.type") record Recursive {
    @id("recursive.next") next:Recursive,
}
@id("app.main") fn main()->i64 {0}
"#;
    // Parsing deliberately reaches the actual index layout gate. Source
    // verification would publish this diagnostic before the constructor owner.
    let program = crate::parse(SOURCE, PATH).unwrap();
    let prelude = crate::prelude::declarations_for_program(&program);
    let old = DeclarationIndex::nominal_original_with_prelude(&program, prelude).unwrap_err();
    let expected = Diagnostic::error(
        "SPX-T217",
        "record declarations contain an illegal by-value recursive layout",
        crate::ast::Span::default(),
    )
    .at_path(PATH);
    assert_eq!(old, expected, "complete independent old six-field receipt");

    let mut requests = Vec::new();
    let (result, overflowed, exact, first) = with_limit_usage_refusal(usize::MAX, || {
        DeclarationIndex::from_verified_with_nominal_reservation(&program, prelude, |n| {
            requests.push(n);
            if reserve_active_required(n) {
                Ok(())
            } else {
                Err(Stop(7))
            }
        })
    });
    assert!(!overflowed);
    assert_eq!(first, None);
    assert!(exact > 0);
    assert!(!requests.is_empty());
    let IdentityIndexError::Semantic(current) = result.unwrap_err() else {
        panic!("unlimited owner unexpectedly refused")
    };
    assert_eq!(current, old);
    drop(current);

    // Every callback includes the actual final diagnostic message/path
    // acquisition; no successful semantic report can hide a refused producer.
    for stop in 0..requests.len() {
        let mut seen = 0;
        let mut at_refusal = 0;
        let (result, allocation) = measure(|| {
            DeclarationIndex::from_verified_with_nominal_reservation(&program, prelude, |n| {
                assert_eq!(n, requests[seen]);
                let at = seen;
                seen += 1;
                if at == stop {
                    at_refusal = current_metrics().allocated;
                    Err(Stop(at))
                } else {
                    Ok(())
                }
            })
        });
        assert!(matches!(result, Err(IdentityIndexError::Identity(Stop(at))) if at == stop));
        assert_eq!(seen, stop + 1, "no callback after selected raw error");
        assert!(!allocation.invalid);
        assert_eq!(allocation.live, 0);
        assert_eq!(allocation.allocated, allocation.freed);
        assert_eq!(
            allocation.allocated, at_refusal,
            "no allocation after refusal, including partial Drop"
        );
    }

    for cap in [0, exact - 1, exact] {
        let ((result, allocation), overflowed, used, first) = with_limit_usage_refusal(cap, || {
            measure(|| {
                DeclarationIndex::from_verified_with_nominal_reservation(&program, prelude, |n| {
                    if reserve_active_required(n) {
                        Ok(())
                    } else {
                        Err(Stop(7))
                    }
                })
            })
        });
        assert!(!allocation.invalid);
        if cap == exact {
            assert!(!overflowed);
            assert_eq!(first, None);
            assert_eq!(used, exact);
            assert!(
                allocation.allocated <= used,
                "actual backing={allocation:?}; paid={used}"
            );
            let IdentityIndexError::Semantic(current) = result.unwrap_err() else {
                panic!("exact owner unexpectedly refused")
            };
            assert_eq!(current, old);
            let ((), disposal) = measure(|| drop(current));
            assert!(!disposal.invalid);
            assert_eq!(
                disposal.allocated, 0,
                "semantic report final Drop allocates nothing"
            );
        } else {
            assert!(matches!(result, Err(IdentityIndexError::Identity(Stop(7)))));
            assert!(overflowed);
            assert!(first.is_some());
            assert_eq!(allocation.live, 0);
            assert_eq!(allocation.allocated, allocation.freed);
            if cap == 0 {
                assert_eq!(allocation.allocated, 0);
            }
        }
    }
    // Keep report allocation and its complete final Drop in one registry.
    // A separate Drop-only observation cannot establish those original frees.
    let (((), allocation), overflowed, used, first) = with_limit_usage_refusal(exact, || {
        measure(|| {
            let result =
                DeclarationIndex::from_verified_with_nominal_reservation(&program, prelude, |n| {
                    if reserve_active_required(n) {
                        Ok(())
                    } else {
                        Err(Stop(7))
                    }
                });
            let IdentityIndexError::Semantic(current) = result.unwrap_err() else {
                panic!("exact complete owner unexpectedly refused")
            };
            assert_eq!(current, old);
            drop(current);
        })
    });
    assert!(!overflowed);
    assert_eq!(first, None);
    assert_eq!(used, exact);
    assert!(!allocation.invalid);
    assert!(allocation.allocated <= used);
    assert_eq!(allocation.live, 0);
    assert_eq!(allocation.allocated, allocation.freed);

    let ((result, allocation), overflowed, used, first) = with_limit_usage_refusal(0, || {
        assert!(!reserve_active_required(1));
        measure(|| {
            DeclarationIndex::from_verified_with_nominal_reservation(&program, prelude, |n| {
                if reserve_active_required(n) {
                    Ok(())
                } else {
                    Err(Stop(9))
                }
            })
        })
    });
    assert!(matches!(result, Err(IdentityIndexError::Identity(Stop(9)))));
    assert!(overflowed);
    assert_eq!(used, 0);
    assert_eq!(first.unwrap().requested, 1);
    assert!(!allocation.invalid);
    assert_eq!(allocation.allocated, 0);
    assert_eq!(allocation.live, 0);
}

//! New explicit finite extension work owner; base-two work is unchanged.
//! Borrows the existing byte owner and cannot lend credit to replay or callers.
use super::fixed_work::{FixedFailure, WorkReceipt, WorkRefusal};
use super::Payer;

// Exact actual work sites in vector_extension::acquire: entry, kind and
// parameter-shape branches, parameter initializer, identity copy, and two
// UTF-8/name byte passes for each of the type and parameter names.
#[cfg(test)]
pub(super) const VECTOR_WORK: usize =
    4 + crate::prelude::VEC_ID.len() + 2 * "Vec".len() + 2 * "T".len();

/// One borrowed same-byte-owner account for one selected extension slot. It owns no
/// heap and no authored/replay work allowance. Keep it through construction and
/// refusal; creating a new invocation is not a retry on this failed account.
pub(super) struct ExtensionPayer<'a, E: Copy> {
    reserve: &'a mut dyn FnMut(usize) -> Result<(), E>,
    limit: usize,
    remaining: usize,
    first: Option<FixedFailure<E>>,
}
impl<'a, E: Copy> ExtensionPayer<'a, E> {
    #[cfg(test)]
    pub(super) fn acquire(reserve: &'a mut dyn FnMut(usize) -> Result<(), E>) -> Result<Self, E> {
        Self::acquire_for(0, reserve)
    }
    pub(super) fn acquire_for(
        slot: usize,
        reserve: &'a mut dyn FnMut(usize) -> Result<(), E>,
    ) -> Result<Self, E> {
        let limit = super::extension_model::WORK[slot];
        let carriers = std::mem::size_of::<Self>()
            .checked_add(std::mem::size_of::<Result<Self, E>>())
            .and_then(|n| n.checked_add(std::mem::size_of::<WorkReceipt>()))
            .expect("fixed producer counter has addressable receiving layouts");
        reserve(carriers)?;
        Ok(Self {
            reserve,
            limit,
            remaining: limit,
            first: None,
        })
    }
    pub(super) fn receipt(&self) -> WorkReceipt {
        WorkReceipt {
            limit: self.limit,
            used: self.limit - self.remaining,
            remaining: self.remaining,
            first: match self.first.as_ref() {
                Some(FixedFailure::Work(first)) => Some(*first),
                _ => None,
            },
        }
    }
    /// Copy the retained inline payload; no Clone requirement, formatting or
    /// callback requery can change an already selected byte/work error.
    pub(super) fn first_failure(&self) -> Option<FixedFailure<E>> {
        self.first.as_ref().map(|first| match first {
            FixedFailure::Bytes(error) => FixedFailure::Bytes(*error),
            FixedFailure::Work(receipt) => FixedFailure::Work(*receipt),
        })
    }
    #[cfg(test)]
    pub(super) fn restrict_for_test(&mut self, limit: usize) {
        assert!(limit <= self.limit);
        assert_eq!(self.limit, self.remaining);
        assert!(self.first.is_none());
        self.limit = limit;
        self.remaining = limit;
    }
}
impl<E: Copy> Payer for ExtensionPayer<'_, E> {
    type Error = FixedFailure<E>;
    fn bytes(&mut self, requested: usize) -> Result<(), Self::Error> {
        if let Some(first) = self.first_failure() {
            return Err(first);
        }
        match (self.reserve)(requested) {
            Ok(()) => Ok(()),
            Err(error) => {
                self.first = Some(FixedFailure::Bytes(error));
                Err(FixedFailure::Bytes(error))
            }
        }
    }
    fn work(&mut self, requested: usize) -> Result<(), Self::Error> {
        if let Some(first) = self.first_failure() {
            return Err(first);
        }
        // Authenticate the original byte owner before selecting work failure,
        // retaining its exact inline E even if its later callback taxonomy changes.
        self.bytes(0)?;
        if requested > self.remaining {
            let first = WorkRefusal {
                requested,
                remaining: self.remaining,
            };
            self.first = Some(FixedFailure::Work(first));
            return Err(FixedFailure::Work(first));
        }
        self.remaining -= requested;
        Ok(())
    }
}

//! Complete per-invocation compiler suffix catalog, in exact source order.
//! No authored schema, process cache, inferred lookup authority, or base work.
use super::*;
use std::mem::size_of;

#[derive(Debug)]
pub(crate) struct VectorExtension {
    pub(super) values: [Option<ResolvedTypeDeclaration>; 9],
}
impl VectorExtension {
    pub(super) fn empty() -> Self {
        Self {
            values: std::array::from_fn(|_| None),
        }
    }
    pub(super) fn text<P: Payer>(value: &str, payer: &mut P) -> Result<String, Failure<P::Error>> {
        // Separate actual helper initializer/conversion/receiving carriers;
        // String backing and its copy/validation work stay with paid::string.
        payer
            .bytes(
                size_of::<String>()
                    + size_of::<Vec<u8>>()
                    + size_of::<Result<String, std::string::FromUtf8Error>>()
                    + size_of::<Result<String, Failure<P::Error>>>(),
            )
            .map_err(Failure::Payer)?;
        paid::string(value, payer)
    }
    #[cfg(test)]
    pub(super) fn acquire<P: Payer>(
        source: &crate::ast::TypeDeclaration,
        payer: &mut P,
    ) -> Result<Self, Failure<P::Error>> {
        payer
            .bytes(
                2 * size_of::<Self>()
                    + size_of::<Option<Self>>()
                    + size_of::<Result<Self, Failure<P::Error>>>(),
            )
            .map_err(Failure::Payer)?;
        let mut value = Self::empty();
        value.values[0] = Some(super::extension_producer::acquire(
            0,
            source,
            &value.values,
            payer,
        )?);
        Ok(value)
    }
    pub(crate) fn for_source<'a>(
        value: Option<&'a Self>,
        prelude: &[crate::ast::TypeDeclaration],
        source: &crate::ast::TypeDeclaration,
    ) -> Option<&'a ResolvedTypeDeclaration> {
        let current = crate::prelude::declarations();
        if !matches!(prelude.len(), 3 | 4 | 6 | 8 | 9 | 11)
            || !std::ptr::eq(prelude, &current[..prelude.len()])
        {
            return None;
        }
        let slot = prelude[2..]
            .iter()
            .position(|item| std::ptr::eq(item, source))?;
        value?.values[slot].as_ref()
    }
}

